-- Step 5a: import wizard (contract, staging, validation, merges, error report).
--
-- * The browser parses CSV/XLSX and sends canonical contract strings in JSON chunks; Postgres
--   re-checks every cell. All validation and merging is static, set-based SQL in security-definer
--   functions over the contract rows in ingest.contract_entities / ingest.contract_columns, which
--   are generated by `uv run maqdar-synth format --sql` (pytest keeps the block below in sync).
-- * Staging lives in the private schema `ingest` (no usage for any API role): one UNLOGGED table
--   of text[] rows in contract order (NULL = column not provided by the file, '' = empty cell),
--   chunk bookkeeping for exact replays, and a scratch table for errors before they are capped
--   and stored. Crash recovery, a failover or a restore empties the unlogged tables while the
--   logged counters stay: app.import_staging_intact compares them before a commit starts, every
--   merge unit first counts the staged rows of its range, and the seal compares the chunk
--   bookkeeping with the file's counter. A loss ends the import as expired with failure_code
--   staging_lost (rows a stepped commit applied before it stay), and the user imports the files
--   again; nothing is ever committed as succeeded from emptied staging.
-- * The creation cap (50 imports per organization in 24 hours) counts an append-only ledger
--   (ingest.import_creations), so deleting imports does not reset it.
-- * Originals: editors may upload only to the server-generated path of a file of an import that is
--   still being checked and whose original is not stored yet, and delete only the originals of
--   finished, canceled or expired imports (set-based helpers app.uploadable_import_paths and
--   app.deletable_import_paths), so a stored audit copy cannot be swapped by delete plus insert.
-- * The supersession and location-parent cycle guards (Step 4) walk the chain with one primary-key
--   probe per step instead of a recursive CTE, whose plan degraded to a scan per row while a merge
--   inserted thousands of rows into a table with stale statistics (quadratic: minutes for 20,000
--   rows). Stepped commits merge supersession, holiday-override and location-parent files of up to
--   10,000 rows in a single unit, so the guards never see a state in between two units.
-- * import_batches, import_files and import_errors are tenant tables written only through the
--   RPCs below and readable by editors only (owner, admin, planner): error values and originals
--   contain demand for every location, so viewers and branch users must not see them.
-- * Commit: up to 5,000 staged rows in one transaction (all or nothing); larger batches in short
--   resumable steps (import_commit_step), at most one committing batch per organization (unique
--   partial index) and every import demand write serialised by the advisory lock
--   maqdar.import:<org>, which app.refuse_delete_with_demand() now takes shared (direct demand
--   writes through the Step 2 editor policies do not take it; the web app makes none). Each step re-resolves references
--   under the lock; a mismatch fails the step instead of dropping rows. Merges only touch rows
--   whose provided columns change, so unchanged rows keep updated_at and search_text.
-- * Default privileges for new public tables and sequences are aligned with hosted Supabase: no
--   automatic SELECT, INSERT, UPDATE or DELETE (tables) or USAGE, SELECT, UPDATE (sequences) for
--   anon, authenticated or service_role; every new object gets explicit grants. service_role loses
--   TRUNCATE, REFERENCES, TRIGGER and MAINTAIN on every public table, now and by default. Demand partitions
--   2020-01..2022-12 are pre-created; imports never create partitions.

set lock_timeout = '5s';

------------------------------------------------------------------------------------------------
-- Privileges: new public tables and sequences are no longer granted to the API roles by default
------------------------------------------------------------------------------------------------

alter default privileges for role postgres in schema public
  revoke select, insert, update, delete on tables from anon, authenticated, service_role;
alter default privileges for role postgres in schema public
  revoke usage, select, update on sequences from anon, authenticated, service_role;

-- No API role holds TRUNCATE, REFERENCES, TRIGGER or MAINTAIN on a public table (Supabase grants
-- them to service_role, which the app only uses for auth.admin calls), now or by default.
revoke truncate, references, trigger, maintain on all tables in schema public from service_role;
alter default privileges for role postgres in schema public
  revoke truncate, references, trigger, maintain on tables from service_role;
-- public_holidays is select-only for authenticated and invisible to anon; so is its sequence.
revoke all on sequence public.public_holidays_id_seq from anon, authenticated;

------------------------------------------------------------------------------------------------
-- Schema ingest: contract and staging, never exposed through the API
------------------------------------------------------------------------------------------------

