  ('supplier_items', 6, 'min_order_quantity', 'decimal', true, false, false, '0', '^-?[0-9]+(\.[0-9]+)?$', null, 3, 12, 0, null, null, null, null, null, 'min_order_quantity'),
  ('supplier_items', 7, 'pack_size', 'decimal', true, false, false, '1', '^-?[0-9]+(\.[0-9]+)?$', null, 3, 12, null, null, 0, null, null, null, 'pack_size'),
  ('supplier_items', 8, 'unit_price', 'money', true, false, true, null, '^-?[0-9]+(\.[0-9]+)?$', null, 3, 12, 0, null, null, null, null, null, 'unit_price'),
  ('supplier_items', 9, 'currency', 'currency', true, false, true, null, '^[A-Z]{3}$', null, null, null, null, null, null, null, 'currencies.code', null, 'currency'),
  ('supplier_items', 10, 'is_preferred', 'boolean', true, false, false, 'false', '^(true|false)$', null, null, null, null, null, null, null, null, null, 'is_preferred'),
  ('supplier_items', 11, 'valid_from', 'date', false, false, false, null, '^[0-9]{4}-[0-9]{2}-[0-9]{2}$', null, null, null, null, null, null, null, null, null, 'valid_from'),
  ('fx_rates', 1, 'from_currency', 'currency', true, true, false, null, '^[A-Z]{3}$', null, null, null, null, null, null, null, 'currencies.code', null, 'from_currency'),
  ('fx_rates', 2, 'to_currency', 'currency', true, true, false, null, '^[A-Z]{3}$', null, null, null, null, null, null, null, 'currencies.code', null, 'to_currency'),
  ('fx_rates', 3, 'valid_from', 'date', true, true, false, null, '^[0-9]{4}-[0-9]{2}-[0-9]{2}$', null, null, null, null, null, null, null, null, null, 'valid_from'),
  ('fx_rates', 4, 'rate', 'decimal', true, false, true, null, '^-?[0-9]+(\.[0-9]+)?$', null, 10, 10, null, null, 0, null, null, null, 'rate'),
  ('fx_rates', 5, 'note', 'text', false, false, false, null, null, 1000, null, null, null, null, null, null, null, null, 'note'),
  ('demand_history', 1, 'item_code', 'item_code', true, true, false, null, '^[A-Za-z0-9][A-Za-z0-9._/-]{0,63}$', 64, null, null, null, null, null, null, 'items.item_code', 'items', 'item_id'),
  ('demand_history', 2, 'location_code', 'code', true, true, false, null, '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$', 64, null, null, null, null, null, null, 'locations.location_code', 'locations', 'location_id'),
  ('demand_history', 3, 'demand_date', 'date', true, true, false, null, '^[0-9]{4}-[0-9]{2}-[0-9]{2}$', null, null, null, null, null, null, null, null, null, 'demand_date'),
  ('demand_history', 4, 'quantity', 'decimal', true, false, false, '0', '^-?[0-9]+(\.[0-9]+)?$', null, 3, 12, 0, null, null, null, null, null, 'quantity'),
  ('demand_history', 5, 'lost_sales_quantity', 'decimal', true, false, false, '0', '^-?[0-9]+(\.[0-9]+)?$', null, 3, 12, 0, null, null, null, null, null, 'lost_sales_quantity');
-- END GENERATED import contract

-- The merge and rule SQL below addresses cells by position. Fail the migration if the generated
-- contract ever disagrees with the positions it was written for, or if a natural key is not made
-- of the leading columns (app.import_nk relies on that).
do $$
declare
  v_bad text;
begin
  select string_agg(e.entity, ', ' order by e.load_order) into v_bad
  from ingest.contract_entities e
  full join (values
    ('work_calendars', array['work_calendar_code', 'name_en', 'name_ar', 'country_code', 'weekend_days', 'observe_public_holidays', 'is_active']),
    ('holiday_overrides', array['country_code', 'work_calendar_code', 'starts_on', 'ends_on', 'kind', 'name_en', 'name_ar', 'note']),
    ('locations', array['location_code', 'name_en', 'name_ar', 'location_type', 'country_code', 'city', 'latitude', 'longitude', 'timezone', 'parent_location_code', 'is_active', 'work_calendar_code']),
    ('network_links', array['from_location_code', 'to_location_code', 'lead_time_days_p50', 'lead_time_days_p90', 'freight_basis', 'freight_cost', 'currency', 'is_active']),
    ('brands', array['brand_code', 'name_en', 'name_ar', 'brand_type', 'country_of_origin', 'is_active']),
    ('items', array['item_code', 'name_en', 'name_ar', 'brand_code', 'product_group', 'unit_of_measure', 'unit_cost', 'currency', 'status', 'introduced_on', 'discontinued_on']),
    ('item_supersessions', array['predecessor_item_code', 'successor_item_code', 'effective_on', 'quantity_factor', 'note']),
    ('item_interchanges', array['item_code', 'alternate_item_code', 'direction', 'priority', 'note']),
    ('suppliers', array['supplier_code', 'name_en', 'name_ar', 'country_code', 'currency', 'lead_time_days_p50', 'lead_time_days_p90', 'is_active', 'work_calendar_code']),
    ('supplier_items', array['supplier_code', 'item_code', 'supplier_part_number', 'lead_time_days', 'lead_time_days_p90', 'min_order_quantity', 'pack_size', 'unit_price', 'currency', 'is_preferred', 'valid_from']),
    ('fx_rates', array['from_currency', 'to_currency', 'valid_from', 'rate', 'note']),
    ('demand_history', array['item_code', 'location_code', 'demand_date', 'quantity', 'lost_sales_quantity'])
  ) as expected (entity, columns) on expected.entity = e.entity
  where e.entity is null
     or expected.entity is null
     or expected.columns is distinct from (select array_agg(c.name order by c.position) from ingest.contract_columns c where c.entity = e.entity)
     or e.natural_key is distinct from expected.columns[1:cardinality(e.natural_key)];
  if v_bad is not null then
    raise exception 'the generated import contract does not match the import functions: %', v_bad;
  end if;
end
$$;

------------------------------------------------------------------------------------------------
-- Staging (UNLOGGED: no WAL, emptied by a crash)
------------------------------------------------------------------------------------------------

create unlogged table ingest.staged_rows (
  organization_id uuid not null,
  batch_id uuid not null,
  file_no smallint not null,
  entity text not null,
  row_no integer not null,
  nk text not null,
  cells text[] not null,
  primary key (batch_id, file_no, row_no)
);
comment on table ingest.staged_rows is 'Rows of the files of open imports in contract order. row_no is the data row (1 = first row after the header); nk is the natural key built by app.import_nk. No foreign keys (cost per row at 1 M rows); every reader filters organization_id and batch_id.';
create unique index staged_rows_batch_entity_nk_key on ingest.staged_rows (batch_id, entity, nk);

create unlogged table ingest.staged_chunks (
  organization_id uuid not null,
  batch_id uuid not null,
  file_no smallint not null,
  first_row_no integer not null,
  last_row_no integer not null,
  row_count integer not null,
  rows_sha256 bytea not null,
  result jsonb not null,
  staged_at timestamptz not null default now(),
  primary key (batch_id, file_no, first_row_no)
);
comment on table ingest.staged_chunks is 'One row per staged chunk: an exact replay returns result, an overlap is refused, seal checks contiguity.';

create unlogged table ingest.pending_errors (
  organization_id uuid not null,
  batch_id uuid not null,
  file_no smallint not null,
  row_no integer not null,
  column_name text not null,
  code text not null,
  level text not null,
  value text,
  detail jsonb
);
comment on table ingest.pending_errors is 'Errors found by the checks of the current call; app.import_flush_errors moves them into import_errors (capped per file) and counts them, in the same transaction.';
create index pending_errors_batch_file_idx on ingest.pending_errors (batch_id, file_no);

-- Logged on purpose: the cap must survive deletes of imports and crashes alike.
create table ingest.import_creations (
  organization_id uuid not null references public.organizations (id) on delete cascade,
  batch_id uuid not null,
  created_at timestamptz not null default now()
);
comment on table ingest.import_creations is 'Append-only ledger of import creations per organization: import_create_batch counts the last 24 hours here (50 at most), so deleting imports does not reset the cap. Rows older than 24 hours are purged by the next creation of the organization.';
create index import_creations_org_created_idx on ingest.import_creations (organization_id, created_at);

alter table ingest.staged_rows enable row level security;
alter table ingest.staged_chunks enable row level security;
alter table ingest.pending_errors enable row level security;
alter table ingest.import_creations enable row level security;
revoke all on ingest.staged_rows, ingest.staged_chunks, ingest.pending_errors, ingest.import_creations
  from public, anon, authenticated, service_role;

------------------------------------------------------------------------------------------------
-- Tenant tables: import_batches, import_files, import_errors (RPC-only, editors read)
------------------------------------------------------------------------------------------------

create table public.import_batches (
  id uuid not null,
  organization_id uuid not null references public.organizations (id) on delete cascade,
  source text not null default 'wizard' check (source in ('wizard', 'api')),
  status text not null default 'staging'
    check (status in ('staging', 'validated', 'invalid', 'committing', 'succeeded', 'failed', 'canceled', 'expired')),
  commit_mode text check (commit_mode is null or commit_mode in ('atomic', 'stepped')),
  created_by uuid references auth.users (id) on delete set null,
  files_sha256 bytea check (files_sha256 is null or octet_length(files_sha256) = 32),
  file_count smallint not null default 0 check (file_count between 0 and 60),
  rows_total integer not null default 0 check (rows_total between 0 and 1000000),
  rows_staged integer not null default 0 check (rows_staged >= 0),
  error_count integer not null default 0 check (error_count >= 0),
  warning_count integer not null default 0 check (warning_count >= 0),
  counts jsonb not null default '{}'::jsonb check (jsonb_typeof(counts) = 'object'),
  progress jsonb not null default '{}'::jsonb check (jsonb_typeof(progress) = 'object'),
  failure_code text check (failure_code is null or failure_code in (
    'changed_during_commit', 'preferred_conflict', 'supersession_cycle', 'location_cycle', 'holiday_overlap',
    'timeout', 'concurrent_change', 'abandoned', 'staging_lost')),
  failure_detail text check (failure_detail is null or char_length(failure_detail) <= 500),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  validated_at timestamptz,
  commit_started_at timestamptz,
  last_step_at timestamptz,
  finished_at timestamptz,
  expires_at timestamptz,
  staging_cleared_at timestamptz,
  primary key (id),
  unique (organization_id, id)
);
comment on table public.import_batches is 'One import: files staged, validated and committed together. id is generated by the client so creation is retry-safe. source api is reserved for Step 5b. Written only through the import_* RPCs; readable by owners, admins and planners.';
comment on column public.import_batches.counts is 'Per entity: inserted, updated, unchanged, deleted, skipped (and parents_set, preferred_cleared where they apply).';
comment on column public.import_batches.progress is 'Stepped commit cursor (phase, file_no, pass, through_row, stats_for), steps and the last 200 unit timings in ms.';
create unique index import_batches_one_committing on public.import_batches (organization_id) where status = 'committing';
create index import_batches_list_idx on public.import_batches (organization_id, created_at desc, id);
create index import_batches_expiry_idx on public.import_batches (expires_at)
  where status in ('staging', 'validated', 'invalid', 'failed');
create index import_batches_cleanup_idx on public.import_batches (finished_at)
  where staging_cleared_at is null and status in ('succeeded', 'canceled', 'expired');
create index import_batches_created_by_idx on public.import_batches (created_by);

create table public.import_files (
  id uuid not null default gen_random_uuid(),
  organization_id uuid not null references public.organizations (id) on delete cascade,
  batch_id uuid not null,
  file_no smallint not null check (file_no between 1 and 60),
  entity text not null check (entity in (
    'work_calendars', 'holiday_overrides', 'locations', 'network_links', 'brands', 'items', 'item_supersessions',
    'item_interchanges', 'suppliers', 'supplier_items', 'fx_rates', 'demand_history')),
  original_name text not null check (char_length(original_name) between 1 and 255),
  content_type text check (content_type is null or char_length(content_type) <= 255),
  extension text not null check (extension in ('csv', 'tsv', 'txt', 'xlsx')),
  size_bytes bigint not null check (size_bytes between 0 and 50000000),
  sha256 bytea not null check (octet_length(sha256) = 32),
  storage_path text not null unique,
  source_stored boolean not null default false,
  header text[] not null default '{}' check (cardinality(header) <= 64),
  columns text[] not null check (cardinality(columns) between 1 and 64),
  mapping jsonb not null default '{}'::jsonb check (jsonb_typeof(mapping) = 'object'),
  parse jsonb not null default '{}'::jsonb check (jsonb_typeof(parse) = 'object'),
  rows_total integer not null check (rows_total between 0 and 1000000),
  rows_staged integer not null default 0 check (rows_staged >= 0),
  rows_new integer not null default 0 check (rows_new >= 0),
  rows_existing integer not null default 0 check (rows_existing >= 0),
  error_count integer not null default 0 check (error_count >= 0),
  warning_count integer not null default 0 check (warning_count >= 0),
  errors_stored integer not null default 0 check (errors_stored between 0 and 10000),
  error_counts jsonb not null default '{}'::jsonb check (jsonb_typeof(error_counts) = 'object'),
  merged_through_row integer not null default 0 check (merged_through_row >= 0),
  counts jsonb not null default '{}'::jsonb check (jsonb_typeof(counts) = 'object'),
  status text not null default 'staging' check (status in ('staging', 'sealed', 'merged')),
  sealed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (id),
  unique (organization_id, id),
  constraint import_files_batch_file_key unique (organization_id, batch_id, file_no),
  constraint import_files_batch_fkey foreign key (organization_id, batch_id)
    references public.import_batches (organization_id, id) on delete cascade,
  constraint import_files_storage_path_check check (
    storage_path = organization_id::text || '/' || batch_id::text || '/' || file_no::text || '.' || extension)
);
comment on table public.import_files is 'Files of an import. columns lists the contract columns the file provides (others are left unchanged); mapping (contract column -> source header) is offered again next time. error_counts is complete ({code: {column: n}}, column '''' for row-level codes) while at most 10,000 details per file are stored in import_errors. storage_path is generated by the server; source_stored tells whether the original reached the imports bucket.';
create index import_files_sha256_idx on public.import_files (organization_id, sha256);
create index import_files_entity_idx on public.import_files (organization_id, entity, created_at desc);

create table public.import_errors (
  id bigint generated always as identity primary key,
  organization_id uuid not null references public.organizations (id) on delete cascade,
  batch_id uuid not null,
  file_no smallint not null check (file_no between 0 and 60),
  row_no integer not null check (row_no >= 0),
  column_name text not null default '' check (char_length(column_name) <= 64),
  code text not null check (code in (
    'required', 'required_for_new', 'too_long', 'invalid_code', 'invalid_item_code', 'invalid_integer',
    'invalid_decimal', 'too_many_decimals', 'too_many_digits', 'out_of_range', 'invalid_date', 'invalid_boolean',
    'invalid_enum', 'invalid_weekdays', 'invalid_timezone', 'unknown_currency', 'unknown_country',
    'unknown_reference', 'duplicate_key', 'end_before_start', 'p90_below_p50',
    'must_differ', 'freight_mismatch', 'country_required', 'scope_exactly_one', 'holiday_too_long',
    'holiday_overlap', 'supersession_cycle', 'location_cycle', 'preferred_conflict',
    'date_outside_history_window', 'source_size_mismatch', 'changed_during_commit', 'concurrent_change',
    'zero_row_new_key', 'source_missing')),
  level text not null check (level in ('error', 'warning')),
  value text check (value is null or char_length(value) <= 200),
  detail jsonb,
  created_at timestamptz not null default now(),
  -- The two warning codes; every other code is an error (import_resume relies on this).
  constraint import_errors_level_matches_code check ((level = 'warning') = (code in ('zero_row_new_key', 'source_missing'))),
  constraint import_errors_batch_fkey foreign key (organization_id, batch_id)
    references public.import_batches (organization_id, id) on delete cascade
);
comment on table public.import_errors is 'Error and warning details of an import (stable machine codes, translated by the web app). row_no is the data row (0 = the whole file); value holds at most 200 characters of the offending cell. Deleted with the import.';
create index import_errors_batch_idx on public.import_errors (organization_id, batch_id, file_no, row_no, id);

create trigger import_batches_set_updated_at
  before update on public.import_batches
  for each row execute function app.set_updated_at();
create trigger import_files_set_updated_at
  before update on public.import_files
  for each row execute function app.set_updated_at();

do $$
declare
  t text;
begin
  foreach t in array array['import_batches', 'import_files', 'import_errors'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon, authenticated, service_role', t);
    execute format('grant select on public.%I to authenticated', t);
    execute format('grant select, delete on public.%I to service_role', t);
    execute format('create policy "editors read" on public.%I for select to authenticated using (organization_id = any (array(select app.editable_organizations())))', t);
  end loop;
end
$$;
revoke all on sequence public.import_errors_id_seq from public, anon, authenticated, service_role;

------------------------------------------------------------------------------------------------
-- Storage: private bucket for the originals (audit copy), editors only, under their organization
------------------------------------------------------------------------------------------------

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'imports', 'imports', false, 50000000,
  array['text/csv', 'text/plain', 'text/tab-separated-values', 'application/vnd.ms-excel',
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'application/octet-stream']
)
on conflict (id) do nothing;

-- Paths are <organization_id>/<batch_id>/<file_no>.<ext>, generated by the server
-- (import_files.storage_path). Uploads go only to the path of a file of an import that is still
-- being checked and whose original is not stored yet (the Storage API checks this when it signs
-- the upload URL); deletes only reach the originals of finished, canceled or expired imports. So
-- nothing else can be uploaded under an organization's prefix, and a stored original cannot be
-- replaced by deleting it and uploading another file to its path. Set-based, like the table
-- policies: each helper is one InitPlan per statement, scoped by app.editable_organizations()
-- (which the token's org_id claim narrows).
create or replace function app.uploadable_import_paths()
returns setof text
language sql
stable
security definer
set search_path = ''
as $$
  select f.storage_path
  from public.import_files f
  join public.import_batches b on b.organization_id = f.organization_id and b.id = f.batch_id
  where f.organization_id = any (array(select app.editable_organizations()))
    and b.status = 'staging'
    and not f.source_stored;
$$;
comment on function app.uploadable_import_paths() is 'Storage paths an editor may upload an original to: files of the editable organizations whose import is staging and whose original is not stored yet.';

create or replace function app.deletable_import_paths()
returns setof text
language sql
stable
security definer
set search_path = ''
as $$
  select f.storage_path
  from public.import_files f
  join public.import_batches b on b.organization_id = f.organization_id and b.id = f.batch_id
  where f.organization_id = any (array(select app.editable_organizations()))
    and b.status in ('succeeded', 'canceled', 'expired');
$$;
comment on function app.deletable_import_paths() is 'Storage paths of originals an editor may delete: files of the editable organizations whose import is succeeded, canceled or expired (the delete flow removes them right before import_delete).';

revoke all on function app.uploadable_import_paths(), app.deletable_import_paths() from public, anon, service_role;
grant execute on function app.uploadable_import_paths(), app.deletable_import_paths() to authenticated;

create policy "editors upload imports"
  on storage.objects for insert to authenticated
  with check (bucket_id = 'imports'
    and name = any (array(select app.uploadable_import_paths())));
-- Reads stay prefix-based: an editor may download any original of the active organization.
-- The first folder is compared as text, so a malformed path is simply denied.
create policy "editors read imports"
  on storage.objects for select to authenticated
  using (bucket_id = 'imports'
    and (storage.foldername(name))[1] = any (array(select o::text from app.editable_organizations() as o)));
create policy "editors delete imports"
  on storage.objects for delete to authenticated
  using (bucket_id = 'imports'
    and name = any (array(select app.deletable_import_paths())));

------------------------------------------------------------------------------------------------
-- Demand window: empty partitions back to 2020-01. Imports never create partitions at runtime.
------------------------------------------------------------------------------------------------

select app.ensure_demand_history_partitions('2020-01-01', '2022-12-01');

------------------------------------------------------------------------------------------------
-- Internal helpers
------------------------------------------------------------------------------------------------

-- MQ401 when signed out; MQ404 when the organization is not one of the caller's (or not the one
-- the token's org_id claim names: a stale tab); MQ403 for members who are not editors.
create or replace function app.require_import_editor(p_organization_id uuid)
returns text
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_role text;
begin
  perform app.require_user();
  if p_organization_id is null
     or not (p_organization_id = any (array(select app.member_organizations()))) then
    raise exception using errcode = 'MQ404', message = 'no such organization', hint = 'organization_id';
  end if;
  v_role := app.membership_role(p_organization_id);
  if v_role is null or not (v_role = any (array['owner', 'admin', 'planner'])) then
    raise exception using errcode = 'MQ403', message = 'importing needs the owner, admin or planner role', hint = 'role';
  end if;
  return v_role;
end;
$$;

-- The batch after authorizing the caller for its organization. MQ404 batch_id when it does not
-- exist or belongs to an organization the caller is not a member of (the same answer, so the id
-- of another organization's import is not confirmed); a member then gets MQ404 organization_id
-- for a stale tab or MQ403 role from app.require_import_editor. Locks the row only afterwards.
-- (import_create_batch is the one exception: a new id that is already taken anywhere is MQ409
-- batch_id, since ids are global; see the comment there.)
create or replace function app.import_batch_for_editor(p_batch_id uuid, p_lock boolean)
returns public.import_batches
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_batch public.import_batches;
begin
  perform app.require_user();
  select * into v_batch from public.import_batches b where b.id = p_batch_id;
  if v_batch.id is null or app.membership_role(v_batch.organization_id) is null then
    raise exception using errcode = 'MQ404', message = 'no such import', hint = 'batch_id';
  end if;
  perform app.require_import_editor(v_batch.organization_id);
  if p_lock then
    select * into v_batch from public.import_batches b where b.id = p_batch_id for update;
    if v_batch.id is null then
      raise exception using errcode = 'MQ404', message = 'no such import', hint = 'batch_id';
    end if;
  end if;
  return v_batch;
end;
$$;

-- Natural key of a staged row: the leading key cells joined by U+001F. Unordered pairs (item
-- interchanges, fx rates) sort their first two parts; holiday overrides use their scope. Each part
-- is cut at 150 characters (valid codes have at most 64) so the key always fits a btree entry.
--
-- Deliberately neither security definer nor SET search_path: it is called once per staged row,
-- and either attribute stops Postgres from inlining it (measured: about 130 µs per call, 2.6 s
-- per 20,000-row chunk, against nothing inlined). It runs only inside the import functions
-- (search_path ''), uses nothing but pg_catalog, and no API role may execute it.
create or replace function app.import_nk(p_entity text, p_cells text[])
returns text
language sql
immutable
parallel safe
as $$
  select case p_entity
    when 'holiday_overrides' then
      (case when coalesce(p_cells[1], '') <> '' then 'country:' || left(p_cells[1], 150)
            when coalesce(p_cells[2], '') <> '' then 'calendar:' || left(p_cells[2], 150)
            else '' end) || E'\x1f' || left(coalesce(p_cells[3], ''), 150)
    when 'item_interchanges' then
      least(left(coalesce(p_cells[1], ''), 150) collate "C", left(coalesce(p_cells[2], ''), 150) collate "C") || E'\x1f'
        || greatest(left(coalesce(p_cells[1], ''), 150) collate "C", left(coalesce(p_cells[2], ''), 150) collate "C")
    when 'fx_rates' then
      least(left(coalesce(p_cells[1], ''), 150) collate "C", left(coalesce(p_cells[2], ''), 150) collate "C") || E'\x1f'
        || greatest(left(coalesce(p_cells[1], ''), 150) collate "C", left(coalesce(p_cells[2], ''), 150) collate "C")
        || E'\x1f' || left(coalesce(p_cells[3], ''), 150)
    when 'network_links' then left(coalesce(p_cells[1], ''), 150) || E'\x1f' || left(coalesce(p_cells[2], ''), 150)
    when 'supplier_items' then left(coalesce(p_cells[1], ''), 150) || E'\x1f' || left(coalesce(p_cells[2], ''), 150)
    when 'demand_history' then
      left(coalesce(p_cells[1], ''), 150) || E'\x1f' || left(coalesce(p_cells[2], ''), 150) || E'\x1f'
        || left(coalesce(p_cells[3], ''), 150)
    else left(coalesce(p_cells[1], ''), 150)
  end;
$$;

-- Which contract columns (by position) a file provides.
create or replace function app.import_provided(p_entity text, p_columns text[])
returns boolean[]
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(array_agg(c.name = any (coalesce(p_columns, '{}'::text[])) order by c.position), '{}'::boolean[])
  from ingest.contract_columns c
  where c.entity = p_entity;
$$;

-- Sums two count objects key by key.
create or replace function app.import_add_counts(p_left jsonb, p_right jsonb)
returns jsonb
language sql
immutable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_object_agg(s.k, s.n), '{}'::jsonb)
  from (
    select x.key as k, sum((x.value)::numeric)::bigint as n
    from (
      select l.key, l.value from jsonb_each(coalesce(p_left, '{}'::jsonb)) as l
      union all
      select r.key, r.value from jsonb_each(coalesce(p_right, '{}'::jsonb)) as r
    ) as x
    where jsonb_typeof(x.value) = 'number'
    group by x.key
  ) as s;
$$;

create or replace function app.import_counts(p_staged integer, p_inserted integer, p_updated integer, p_deleted integer, p_skipped integer)
returns jsonb
language sql
immutable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'inserted', p_inserted,
    'updated', p_updated,
    'unchanged', greatest(p_staged - p_inserted - p_updated - p_deleted - p_skipped, 0),
    'deleted', p_deleted,
    'skipped', p_skipped);
$$;

create or replace function app.import_append_timing(p_timings jsonb, p_unit text, p_ms integer)
returns jsonb
language sql
immutable
security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(t.x order by t.i), '[]'::jsonb)
  from (
    select a.x, a.i
    from jsonb_array_elements(coalesce(p_timings, '[]'::jsonb) || jsonb_build_array(jsonb_build_object('unit', p_unit, 'ms', p_ms))) with ordinality as a(x, i)
    order by a.i desc
    limit 200
  ) as t;
$$;

-- The demand dates imports accept: the existing monthly partitions (created only by migrations,
-- contiguous) and at most tomorrow.
create or replace function app.demand_history_window()
returns daterange
language sql
stable
security definer
set search_path = ''
as $$
  select daterange(min(b.lower_bound), greatest(min(b.lower_bound), least(max(b.upper_bound), current_date + 2)), '[)')
  from (
    select m[1]::date as lower_bound, m[2]::date as upper_bound
    from pg_catalog.pg_inherits i
    join pg_catalog.pg_class c on c.oid = i.inhrelid
    cross join lateral regexp_match(
      pg_catalog.pg_get_expr(c.relpartbound, c.oid),
      'FROM \(''([0-9]{4}-[0-9]{2}-[0-9]{2})''\) TO \(''([0-9]{4}-[0-9]{2}-[0-9]{2})''\)') as m
    where i.inhparent = 'public.demand_history'::regclass
  ) as b;
$$;

------------------------------------------------------------------------------------------------
-- Errors: checks write to ingest.pending_errors, the flush caps, stores and counts them
------------------------------------------------------------------------------------------------

create or replace function app.import_flush_errors(p_batch_id uuid, p_file_no smallint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org uuid;
  v_room integer;
  v_stored integer;
  v_errors integer;
  v_warnings integer;
  v_counts jsonb;
begin
  select f.organization_id, greatest(0, 10000 - f.errors_stored) into v_org, v_room
  from public.import_files f
  where f.batch_id = p_batch_id and f.file_no = p_file_no;

  with moved as (
    delete from ingest.pending_errors p
    where p.batch_id = p_batch_id and p.file_no = p_file_no and p.organization_id = v_org
    returning p.row_no, p.column_name, p.code, p.level, p.value, p.detail
  ), stored as (
    insert into public.import_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value, detail)
    select v_org, p_batch_id, p_file_no, m.row_no, m.column_name, m.code, m.level, left(m.value, 200), m.detail
    from moved m
    order by m.row_no, m.column_name, m.code
    limit v_room
    returning 1
  ), grouped as (
    select m.code, m.column_name, m.level, count(*)::integer as n
    from moved m
    group by m.code, m.column_name, m.level
  )
  select (select count(*)::integer from stored),
         coalesce(sum(g.n) filter (where g.level = 'error'), 0)::integer,
         coalesce(sum(g.n) filter (where g.level = 'warning'), 0)::integer,
         coalesce(jsonb_agg(jsonb_build_object('code', g.code, 'column', g.column_name, 'count', g.n)), '[]'::jsonb)
    into v_stored, v_errors, v_warnings, v_counts
  from grouped g;

  if v_errors + v_warnings > 0 then
    update public.import_files f
    set error_count = f.error_count + v_errors,
        warning_count = f.warning_count + v_warnings,
        errors_stored = f.errors_stored + v_stored,
        error_counts = (
          select coalesce(jsonb_object_agg(a.code, a.columns), '{}'::jsonb)
          from (
            select b.code, jsonb_object_agg(b.column_name, b.n) as columns
            from (
              select c.code, c.column_name, sum(c.n)::integer as n
              from (
                select o.key as code, i.key as column_name, (i.value)::integer as n
                from jsonb_each(f.error_counts) as o
                cross join lateral jsonb_each(o.value) as i
                union all
                select x ->> 'code', x ->> 'column', (x ->> 'count')::integer
                from jsonb_array_elements(v_counts) as x
              ) as c
              group by c.code, c.column_name
            ) as b
            group by b.code
          ) as a)
    where f.batch_id = p_batch_id and f.file_no = p_file_no;

    update public.import_batches b
    set error_count = b.error_count + v_errors,
        warning_count = b.warning_count + v_warnings
    where b.id = p_batch_id;
  end if;

  return jsonb_build_object('errors', v_errors, 'warnings', v_warnings, 'stored', v_stored);
end;
$$;

-- One file-level error (row 0), stored and counted at once.
create or replace function app.import_add_error(p_batch_id uuid, p_file_no smallint, p_code text, p_detail jsonb)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into ingest.pending_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value, detail)
  select f.organization_id, f.batch_id, f.file_no, 0, '', p_code, 'error', null, p_detail
  from public.import_files f
  where f.batch_id = p_batch_id and f.file_no = p_file_no;
  perform app.import_flush_errors(p_batch_id, p_file_no);
end;
$$;

------------------------------------------------------------------------------------------------
-- Checks
------------------------------------------------------------------------------------------------

-- Every provided cell against its contract column: one static statement. The first failing code
-- per cell wins: required, too_long, the kind's pattern code, invalid_enum, invalid_date,
-- invalid_weekdays, invalid_timezone, unknown_currency, unknown_country, too_many_digits,
-- too_many_decimals (trailing fractional zeros do not count), out_of_range.
create or replace function app.import_check_cells(p_batch_id uuid, p_file_no smallint, p_first_row integer, p_last_row integer)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org uuid;
  v_entity text;
  v_columns text[];
  v_currencies text[];
  v_countries text[];
  v_zones text[] := '{}';
  v_found integer;
begin
  select f.organization_id, f.entity, f.columns into v_org, v_entity, v_columns
  from public.import_files f
  where f.batch_id = p_batch_id and f.file_no = p_file_no;

  v_currencies := array(select c.code::text from public.currencies c);
  v_countries := array(select c.code::text from public.countries c);
  if exists (select 1 from ingest.contract_columns c
             where c.entity = v_entity and c.kind = 'timezone' and c.name = any (v_columns)) then
    v_zones := array(select z.name from pg_catalog.pg_timezone_names z
                     where z.name not in ('Factory', 'localtime', 'posixrules') and lower(z.name) <> 'etc/unknown');
  end if;

  insert into ingest.pending_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value)
  select v_org, p_batch_id, p_file_no, x.row_no, x.name, x.code, 'error', left(x.v, 200)
  from (
    select s.row_no, c.name, u.v,
      case
        when u.v = '' then case when c.required then 'required' end
        when c.max_length is not null and char_length(u.v) > c.max_length then 'too_long'
        when c.pattern is not null and u.v !~ c.pattern then
          case c.kind
            when 'code' then 'invalid_code'
            when 'item_code' then 'invalid_item_code'
            when 'integer' then 'invalid_integer'
            when 'decimal' then 'invalid_decimal'
            when 'money' then 'invalid_decimal'
            when 'currency' then 'unknown_currency'
            when 'country' then 'unknown_country'
            when 'date' then 'invalid_date'
            when 'boolean' then 'invalid_boolean'
            when 'weekdays' then 'invalid_weekdays'
            when 'timezone' then 'invalid_timezone'
            else 'invalid_code'
          end
        when c.kind = 'enum' and not (u.v = any (c.enum_values)) then 'invalid_enum'
        when c.kind = 'date' and not pg_catalog.pg_input_is_valid(u.v, 'date') then 'invalid_date'
        when c.kind = 'weekdays'
             and (select count(distinct d) from unnest(string_to_array(u.v, ';')) as d) <> cardinality(string_to_array(u.v, ';'))
          then 'invalid_weekdays'
        when c.kind = 'timezone' and not (u.v = any (v_zones)) then 'invalid_timezone'
        when c.kind = 'currency' and not (u.v = any (v_currencies)) then 'unknown_currency'
        when c.kind = 'country' and c.reference = 'countries.code' and not (u.v = any (v_countries)) then 'unknown_country'
        when c.integer_digits is not null
             and char_length(ltrim(split_part(ltrim(u.v, '-'), '.', 1), '0')) > c.integer_digits then 'too_many_digits'
        when c.scale is not null and char_length(rtrim(split_part(u.v, '.', 2), '0')) > c.scale then 'too_many_decimals'
        when c.min_value is not null and u.v::numeric < c.min_value then 'out_of_range'
        when c.max_value is not null and u.v::numeric > c.max_value then 'out_of_range'
        when c.greater_than is not null and u.v::numeric <= c.greater_than then 'out_of_range'
      end as code
    from ingest.staged_rows s
    cross join lateral unnest(s.cells) with ordinality as u(v, position)
    join ingest.contract_columns c on c.entity = s.entity and c.position = u.position
    where s.organization_id = v_org
      and s.batch_id = p_batch_id
      and s.file_no = p_file_no
      and s.row_no between p_first_row and p_last_row
      and u.v is not null
  ) as x
  where x.code is not null;
  get diagnostics v_found = row_count;
  return v_found;
end;
$$;

-- References, row rules, existing keys and required-for-new for a row range.
--   p_phase 'stage': references to the target and to the batch's staged parent rows (parent files
--     are sealed before a child file stages), row rules, the demand window, rows_new and
--     rows_existing, zero_row_new_key warnings.
--   p_phase 'commit' (under the import lock): references, required_for_new and the row rules over
--     effective values (country_required, items end_before_start, supplier_items p90_below_p50),
--     recorded with detail {"phase": "commit"}.
-- Self-references (a location's parent) are checked at seal by app.import_check_sets.
create or replace function app.import_check_refs(p_batch_id uuid, p_file_no smallint, p_first_row integer, p_last_row integer, p_phase text)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org uuid;
  v_entity text;
  v_columns text[];
  v_missing text[];
  v_lookup_positions smallint[];
  v_lookup_names text[];
  v_lookup_entities text[];
  v_lookup_patterns text[];
  v_window daterange;
  v_detail jsonb := case when p_phase = 'commit' then '{"phase": "commit"}'::jsonb end;
  v_found integer := 0;
  v_n integer;
  v_existing integer;
  v_new integer;
  v_first_day date;
  v_last_day date;
begin
  select f.organization_id, f.entity, f.columns into v_org, v_entity, v_columns
  from public.import_files f
  where f.batch_id = p_batch_id and f.file_no = p_file_no;

  -- Codes that name rows of another entity: distinct values first, then the target's natural-key
  -- index and the staging key index, then back to the rows. Both CTEs are materialized: the
  -- staging table has no useful statistics mid-import, and a planner that believes v holds one row
  -- re-evaluates the distinct lookups once per row of v (19 s for a 20,000-row chunk).
  select array_agg(c.position order by c.position), array_agg(c.name order by c.position),
         array_agg(c.lookup_entity order by c.position), array_agg(c.pattern order by c.position)
    into v_lookup_positions, v_lookup_names, v_lookup_entities, v_lookup_patterns
  from ingest.contract_columns c
  where c.entity = v_entity and c.lookup_entity is not null and c.lookup_entity <> v_entity
    and c.name = any (v_columns);
  with v as materialized (
    select r.row_no, c.name, c.lookup_entity, r.cells[c.position] as code
    from ingest.staged_rows r
    cross join unnest(v_lookup_positions, v_lookup_names, v_lookup_entities, v_lookup_patterns)
      as c(position, name, lookup_entity, pattern)
    where r.organization_id = v_org
      and r.batch_id = p_batch_id
      and r.file_no = p_file_no
      and r.row_no between p_first_row and p_last_row
      and r.cells[c.position] <> ''
      and r.cells[c.position] ~ c.pattern
  ), missing as materialized (
    select d.lookup_entity, d.code
    from (select distinct v.lookup_entity, v.code from v) as d
    where not exists (
        select 1 from ingest.staged_rows p
        where p.batch_id = p_batch_id and p.entity = d.lookup_entity and p.nk = d.code and p.organization_id = v_org)
      and not (case d.lookup_entity
        when 'items' then exists (select 1 from public.items t where t.organization_id = v_org and t.code = d.code)
        when 'locations' then exists (select 1 from public.locations t where t.organization_id = v_org and t.code = d.code)
        when 'brands' then exists (select 1 from public.brands t where t.organization_id = v_org and t.code = d.code)
        when 'suppliers' then exists (select 1 from public.suppliers t where t.organization_id = v_org and t.code = d.code)
        when 'work_calendars' then exists (select 1 from public.work_calendars t where t.organization_id = v_org and t.code = d.code)
        else false
      end)
  )
  insert into ingest.pending_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value, detail)
  select v_org, p_batch_id, p_file_no, v.row_no, v.name, 'unknown_reference', 'error', v.code, v_detail
  from v
  join missing m on m.lookup_entity = v.lookup_entity and m.code = v.code;
  get diagnostics v_n = row_count;
  v_found := v_found + v_n;

  if p_phase = 'stage' then
    if v_entity = 'demand_history' then
      v_window := app.demand_history_window();
    end if;
    with r as (
      select s.row_no, s.cells
      from ingest.staged_rows s
      where s.organization_id = v_org
        and s.batch_id = p_batch_id
        and s.file_no = p_file_no
        and s.row_no between p_first_row and p_last_row
    )
    insert into ingest.pending_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value)
    select v_org, p_batch_id, p_file_no, x.row_no, x.column_name, x.code, 'error', left(x.value, 200)
    from (
      select r.row_no, 'country_code' as column_name, 'scope_exactly_one' as code, coalesce(r.cells[1], '') as value
      from r
      where v_entity = 'holiday_overrides'
        and (coalesce(r.cells[1], '') <> '') = (coalesce(r.cells[2], '') <> '')
      union all
      select r.row_no, 'ends_on', 'end_before_start', r.cells[4]
      from r
      where v_entity = 'holiday_overrides'
        and case when r.cells[3] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(r.cells[3], 'date')
                  and r.cells[4] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(r.cells[4], 'date')
                 then r.cells[4]::date < r.cells[3]::date else false end
      union all
      select r.row_no, 'ends_on', 'holiday_too_long', r.cells[4]
      from r
      where v_entity = 'holiday_overrides'
        and case when r.cells[3] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(r.cells[3], 'date')
                  and r.cells[4] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(r.cells[4], 'date')
                 then r.cells[4]::date - r.cells[3]::date >= 366 else false end
      union all
      select r.row_no, 'parent_location_code', 'must_differ', r.cells[10]
      from r
      where v_entity = 'locations' and r.cells[10] <> '' and r.cells[10] = r.cells[1]
      union all
      select r.row_no, 'to_location_code', 'must_differ', r.cells[2]
      from r
      where v_entity = 'network_links' and r.cells[1] <> '' and r.cells[1] = r.cells[2]
      union all
      select r.row_no, 'lead_time_days_p90', 'p90_below_p50', r.cells[4]
      from r
      where v_entity = 'network_links'
        and case when r.cells[3] ~ '^-?[0-9]+$' and r.cells[4] ~ '^-?[0-9]+$'
                 then r.cells[4]::numeric < r.cells[3]::numeric else false end
      union all
      select r.row_no, 'freight_cost', 'freight_mismatch', r.cells[6]
      from r
      where v_entity = 'network_links'
        and case r.cells[5]
              when 'none' then coalesce(r.cells[6], '') <> '' or coalesce(r.cells[7], '') <> ''
              when 'per_unit' then coalesce(r.cells[6], '') = '' or coalesce(r.cells[7], '') = ''
              when 'per_shipment' then coalesce(r.cells[6], '') = '' or coalesce(r.cells[7], '') = ''
              else false
            end
      union all
      select r.row_no, 'successor_item_code', 'must_differ', r.cells[2]
      from r
      where v_entity = 'item_supersessions' and r.cells[1] <> '' and r.cells[1] = r.cells[2]
      union all
      select r.row_no, 'alternate_item_code', 'must_differ', r.cells[2]
      from r
      where v_entity = 'item_interchanges' and r.cells[1] <> '' and r.cells[1] = r.cells[2]
      union all
      select r.row_no, 'lead_time_days_p90', 'p90_below_p50', r.cells[7]
      from r
      where v_entity = 'suppliers'
        and case when r.cells[6] ~ '^-?[0-9]+$' and r.cells[7] ~ '^-?[0-9]+$'
                 then r.cells[7]::numeric < r.cells[6]::numeric else false end
      union all
      select r.row_no, 'to_currency', 'must_differ', r.cells[2]
      from r
      where v_entity = 'fx_rates' and r.cells[1] <> '' and r.cells[1] = r.cells[2]
      union all
      select r.row_no, 'demand_date', 'date_outside_history_window', r.cells[3]
      from r
      where v_entity = 'demand_history'
        and case when r.cells[3] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(r.cells[3], 'date')
                 then not (r.cells[3]::date <@ v_window) else false end
    ) as x;
    get diagnostics v_n = row_count;
    v_found := v_found + v_n;
  end if;

  -- Row rules over effective values: the provided value, else the stored value of the existing
  -- row, else the default a new row gets (observe_public_holidays true; the dates and
  -- lead_time_days_p90 empty). These columns are not column groups, so a file may map one side
  -- only. Both phases run them: a stored value can change between validation and commit, and the
  -- merge would then hit the table's CHECK (23514) instead of reporting the row. An empty cell
  -- means no value; an invalid one takes no part (the cell check reports it). The error names the
  -- rule's column when the file provides it, else the other column the file provides;
  -- detail.stored has the stored values the comparison used. The lateral LIMIT 1 keeps each lookup
  -- an index probe whatever the staging statistics say.
  if v_entity = 'work_calendars'
     or (v_entity = 'items' and v_columns && array['introduced_on', 'discontinued_on'])
     or (v_entity = 'supplier_items' and v_columns && array['lead_time_days', 'lead_time_days_p90']) then
    with r as (
      select s.row_no, s.cells
      from ingest.staged_rows s
      where s.organization_id = v_org
        and s.batch_id = p_batch_id
        and s.file_no = p_file_no
        and s.row_no between p_first_row and p_last_row
    ), y as (
      -- work_calendars: observe_public_holidays needs a country_code
      select x.row_no, 'country_required' as code,
             case when x.country_cell is null and x.observe_cell is not null then 'observe_public_holidays'
                  else 'country_code' end as column_name,
             case when x.country_cell is null and x.observe_cell is not null then x.observe_cell
                  else x.country_cell end as value,
             jsonb_strip_nulls(jsonb_build_object(
               'observe_public_holidays', case when x.observe_cell is null then x.stored_observe end)) as stored
      from (
        select r.row_no, r.cells[4] as country_cell, r.cells[6] as observe_cell,
               t.observe_public_holidays as stored_observe,
               case when r.cells[6] is not null then r.cells[6] = 'true'
                    else coalesce(t.observe_public_holidays, true) end as observing,
               case when r.cells[4] is not null then nullif(r.cells[4], '')
                    else t.country_code::text end as country
        from r
        left join lateral (
          select w.country_code, w.observe_public_holidays
          from public.work_calendars w
          where w.organization_id = v_org and w.code = r.cells[1]
          limit 1
        ) as t on true
        where v_entity = 'work_calendars'
      ) as x
      where x.observing and x.country is null
      union all
      -- items: discontinued_on on or after introduced_on
      select x.row_no, 'end_before_start',
             case when x.end_cell is not null then 'discontinued_on' else 'introduced_on' end,
             case when x.end_cell is not null then x.end_cell else x.start_cell end,
             jsonb_strip_nulls(jsonb_build_object(
               'introduced_on', case when x.start_cell is null then x.stored_start end,
               'discontinued_on', case when x.end_cell is null then x.stored_end end))
      from (
        select r.row_no, r.cells[10] as start_cell, r.cells[11] as end_cell,
               t.introduced_on as stored_start, t.discontinued_on as stored_end,
               case when r.cells[10] is null then t.introduced_on
                    when r.cells[10] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(r.cells[10], 'date')
                      then r.cells[10]::date end as start_on,
               case when r.cells[11] is null then t.discontinued_on
                    when r.cells[11] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(r.cells[11], 'date')
                      then r.cells[11]::date end as end_on
        from r
        left join lateral (
          select i.introduced_on, i.discontinued_on
          from public.items i
          where i.organization_id = v_org and i.code = r.cells[1]
          limit 1
        ) as t on true
        where v_entity = 'items' and (r.cells[10] is not null or r.cells[11] is not null)
      ) as x
      where x.end_on < x.start_on
      union all
      -- supplier_items: lead_time_days_p90 empty or at least lead_time_days
      select x.row_no, 'p90_below_p50',
             case when x.p90_cell is not null then 'lead_time_days_p90' else 'lead_time_days' end,
             case when x.p90_cell is not null then x.p90_cell else x.p50_cell end,
             jsonb_strip_nulls(jsonb_build_object(
               'lead_time_days', case when x.p50_cell is null then x.stored_p50 end,
               'lead_time_days_p90', case when x.p90_cell is null then x.stored_p90 end))
      from (
        select r.row_no, r.cells[4] as p50_cell, r.cells[5] as p90_cell,
               t.lead_time_days as stored_p50, t.lead_time_days_p90 as stored_p90,
               case when r.cells[4] is null then t.lead_time_days::numeric
                    when r.cells[4] ~ '^-?[0-9]+$' then r.cells[4]::numeric end as p50,
               case when r.cells[5] is null then t.lead_time_days_p90::numeric
                    when r.cells[5] ~ '^-?[0-9]+$' then r.cells[5]::numeric end as p90
        from r
        left join lateral (
          select si.lead_time_days, si.lead_time_days_p90
          from public.suppliers a
          join public.items b on b.organization_id = a.organization_id and b.code = r.cells[2]
          join public.supplier_items si
            on si.organization_id = a.organization_id and si.supplier_id = a.id and si.item_id = b.id
          where a.organization_id = v_org and a.code = r.cells[1]
          limit 1
        ) as t on true
        where v_entity = 'supplier_items' and (r.cells[4] is not null or r.cells[5] is not null)
      ) as x
      where x.p90 < x.p50
    )
    insert into ingest.pending_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value, detail)
    select v_org, p_batch_id, p_file_no, y.row_no, y.column_name, y.code, 'error', left(y.value, 200),
           nullif(coalesce(v_detail, '{}'::jsonb)
                  || case when y.stored <> '{}'::jsonb then jsonb_build_object('stored', y.stored) else '{}'::jsonb end,
                  '{}'::jsonb)
    from y;
    get diagnostics v_n = row_count;
    v_found := v_found + v_n;
  end if;

  -- Existing keys: rows_new / rows_existing, required_for_new on new keys for every
  -- required-for-new column the file does not provide, and (demand) zero rows for keys that do not
  -- exist, which the merge skips.
  v_missing := array(
    select c.name from ingest.contract_columns c
    where c.entity = v_entity and c.required_for_new and not (c.name = any (v_columns))
    order by c.position);
  if v_entity = 'demand_history' then
    -- One primary-key probe per row, limited to the partitions of the chunk's date range. The
    -- lateral LIMIT 1 keeps it a probe whatever the staging statistics say (a hash join would read
    -- the organization's demand for the whole range).
    if p_phase = 'stage' then
      select min(d.day), max(d.day) into v_first_day, v_last_day
      from (
        select case when r.cells[3] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(r.cells[3], 'date')
                    then r.cells[3]::date end as day
        from ingest.staged_rows r
        where r.organization_id = v_org and r.batch_id = p_batch_id and r.file_no = p_file_no
          and r.row_no between p_first_row and p_last_row
      ) as d;
      perform app.import_analyze_demand_months(v_first_day, v_last_day);
      with e as materialized (
        select r.row_no, r.cells, d.found is not null as found
        from ingest.staged_rows r
        left join public.items i on i.organization_id = v_org and i.code = r.cells[1]
        left join public.locations l on l.organization_id = v_org and l.code = r.cells[2]
        left join lateral (
          select true as found
          from public.demand_history d
          where d.organization_id = v_org and d.item_id = i.id and d.location_id = l.id
            and d.demand_date = case when r.cells[3] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
                                          and pg_catalog.pg_input_is_valid(r.cells[3], 'date') then r.cells[3]::date end
            and d.demand_date between v_first_day and v_last_day
          limit 1
        ) as d on true
        where r.organization_id = v_org
          and r.batch_id = p_batch_id
          and r.file_no = p_file_no
          and r.row_no between p_first_row and p_last_row
      ), zero as (
        insert into ingest.pending_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value, detail)
        select v_org, p_batch_id, p_file_no, e.row_no, '', 'zero_row_new_key', 'warning', null, null
        from e
        where not e.found
          and coalesce(case when e.cells[4] is null then 0::numeric
                            when e.cells[4] ~ '^[0-9]+(\.[0-9]+)?$' then e.cells[4]::numeric end, -1) = 0
          and coalesce(case when e.cells[5] is null then 0::numeric
                            when e.cells[5] ~ '^[0-9]+(\.[0-9]+)?$' then e.cells[5]::numeric end, -1) = 0
        returning 1
      )
      select count(*) filter (where e.found)::integer, count(*) filter (where not e.found)::integer
        into v_existing, v_new
      from e;
      update public.import_files f
      set rows_new = f.rows_new + v_new, rows_existing = f.rows_existing + v_existing
      where f.batch_id = p_batch_id and f.file_no = p_file_no;
    end if;
  elsif p_phase = 'stage' or cardinality(v_missing) > 0 then
    with e as materialized (
      select r.row_no,
        case v_entity
          when 'work_calendars' then exists (
            select 1 from public.work_calendars t where t.organization_id = v_org and t.code = r.cells[1])
          when 'holiday_overrides' then case
            when r.cells[3] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(r.cells[3], 'date') then exists (
              select 1 from public.holiday_overrides t
              where t.organization_id = v_org
                and t.starts_on = r.cells[3]::date
                and t.scope_key = case
                  when coalesce(r.cells[1], '') <> '' then 'country:' || r.cells[1]
                  else 'calendar:' || (select w.id::text from public.work_calendars w
                                       where w.organization_id = v_org and w.code = r.cells[2]) end)
            else false end
          when 'locations' then exists (
            select 1 from public.locations t where t.organization_id = v_org and t.code = r.cells[1])
          when 'network_links' then exists (
            select 1
            from public.locations a
            join public.locations b on b.organization_id = a.organization_id and b.code = r.cells[2]
            join public.network_links t
              on t.organization_id = a.organization_id and t.from_location_id = a.id and t.to_location_id = b.id
            where a.organization_id = v_org and a.code = r.cells[1])
          when 'brands' then exists (
            select 1 from public.brands t where t.organization_id = v_org and t.code = r.cells[1])
          when 'items' then exists (
            select 1 from public.items t where t.organization_id = v_org and t.code = r.cells[1])
          when 'item_supersessions' then exists (
            select 1
            from public.items p
            join public.item_supersessions t on t.organization_id = p.organization_id and t.predecessor_item_id = p.id
            where p.organization_id = v_org and p.code = r.cells[1])
          when 'item_interchanges' then exists (
            select 1
            from public.items a
            join public.items b on b.organization_id = a.organization_id and b.code = r.cells[2]
            join public.item_interchanges t
              on t.organization_id = a.organization_id
             and least(t.item_id, t.alternate_item_id) = least(a.id, b.id)
             and greatest(t.item_id, t.alternate_item_id) = greatest(a.id, b.id)
            where a.organization_id = v_org and a.code = r.cells[1])
          when 'suppliers' then exists (
            select 1 from public.suppliers t where t.organization_id = v_org and t.code = r.cells[1])
          when 'supplier_items' then exists (
            select 1
            from public.suppliers a
            join public.items b on b.organization_id = a.organization_id and b.code = r.cells[2]
            join public.supplier_items t
              on t.organization_id = a.organization_id and t.supplier_id = a.id and t.item_id = b.id
            where a.organization_id = v_org and a.code = r.cells[1])
          when 'fx_rates' then case
            when r.cells[1] ~ '^[A-Z]{3}$' and r.cells[2] ~ '^[A-Z]{3}$'
                 and r.cells[3] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(r.cells[3], 'date') then exists (
              select 1 from public.fx_rates t
              where t.organization_id = v_org
                and least(t.from_currency, t.to_currency) = least(r.cells[1]::char(3), r.cells[2]::char(3))
                and greatest(t.from_currency, t.to_currency) = greatest(r.cells[1]::char(3), r.cells[2]::char(3))
                and t.valid_from = r.cells[3]::date)
            else false end
          else false
        end as found
      from ingest.staged_rows r
      where r.organization_id = v_org
        and r.batch_id = p_batch_id
        and r.file_no = p_file_no
        and r.row_no between p_first_row and p_last_row
    ), rfn as (
      insert into ingest.pending_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value, detail)
      select v_org, p_batch_id, p_file_no, e.row_no, m.name, 'required_for_new', 'error', null, v_detail
      from e
      cross join unnest(v_missing) as m(name)
      where not e.found
      returning 1
    )
    select count(*) filter (where e.found)::integer, count(*) filter (where not e.found)::integer,
           (select count(*)::integer from rfn)
      into v_existing, v_new, v_n
    from e;
    v_found := v_found + v_n;
    if p_phase = 'stage' then
      update public.import_files f
      set rows_new = f.rows_new + v_new, rows_existing = f.rows_existing + v_existing
      where f.batch_id = p_batch_id and f.file_no = p_file_no;
    end if;
  end if;

  return v_found;
end;
$$;

-- Rules over a whole file, run at seal: location parents within the file, location_cycle,
-- supersession_cycle (each with the stored edges the file does not replace), preferred_conflict
-- and holiday_overlap (within the file and with stored overrides it does not replace).
create or replace function app.import_check_sets(p_batch_id uuid, p_file_no smallint)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org uuid;
  v_entity text;
  v_columns text[];
  v_pattern text;
  v_found integer := 0;
  v_n integer;
begin
  select f.organization_id, f.entity, f.columns into v_org, v_entity, v_columns
  from public.import_files f
  where f.batch_id = p_batch_id and f.file_no = p_file_no;

  if v_entity = 'locations' and 'parent_location_code' = any (v_columns) then
    select c.pattern into v_pattern from ingest.contract_columns c
    where c.entity = 'locations' and c.name = 'parent_location_code';
    insert into ingest.pending_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value)
    select v_org, p_batch_id, p_file_no, s.row_no, 'parent_location_code', 'unknown_reference', 'error', s.cells[10]
    from ingest.staged_rows s
    where s.organization_id = v_org
      and s.batch_id = p_batch_id
      and s.file_no = p_file_no
      and s.cells[10] <> ''
      and s.cells[10] ~ v_pattern
      and not exists (select 1 from ingest.staged_rows p
                      where p.batch_id = p_batch_id and p.entity = 'locations' and p.nk = s.cells[10] and p.organization_id = v_org)
      and not exists (select 1 from public.locations t where t.organization_id = v_org and t.code = s.cells[10]);
    get diagnostics v_n = row_count;
    v_found := v_found + v_n;

    with recursive file_rows as (
      select s.row_no, s.cells[1] as code, nullif(s.cells[10], '') as parent
      from ingest.staged_rows s
      where s.organization_id = v_org and s.batch_id = p_batch_id and s.file_no = p_file_no
    ), edges as (
      select f.code as child, f.parent from file_rows f where f.parent is not null
      union all
      select l.code, p.code
      from public.locations l
      join public.locations p on p.organization_id = l.organization_id and p.id = l.parent_location_id
      where l.organization_id = v_org
        and not exists (select 1 from file_rows f where f.code = l.code)
    ), walk (start_row, start_code, node) as (
      select f.row_no, f.code, f.parent from file_rows f where f.parent is not null
      union
      select w.start_row, w.start_code, e.parent
      from walk w
      join edges e on e.child = w.node
      where w.node <> w.start_code
    )
    insert into ingest.pending_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value)
    select v_org, p_batch_id, p_file_no, f.row_no, 'parent_location_code', 'location_cycle', 'error', f.parent
    from file_rows f
    where exists (select 1 from walk w where w.start_row = f.row_no and w.node = w.start_code);
    get diagnostics v_n = row_count;
    v_found := v_found + v_n;
  end if;

  if v_entity = 'item_supersessions' and 'successor_item_code' = any (v_columns) then
    with recursive file_rows as (
      select s.row_no, s.cells[1] as code, nullif(s.cells[2], '') as successor
      from ingest.staged_rows s
      where s.organization_id = v_org and s.batch_id = p_batch_id and s.file_no = p_file_no
    ), edges as (
      select f.code as predecessor, f.successor from file_rows f where f.successor is not null
      union all
      select a.code, b.code
      from public.item_supersessions t
      join public.items a on a.organization_id = t.organization_id and a.id = t.predecessor_item_id
      join public.items b on b.organization_id = t.organization_id and b.id = t.successor_item_id
      where t.organization_id = v_org
        and not exists (select 1 from file_rows f where f.code = a.code)
    ), walk (start_row, start_code, node) as (
      select f.row_no, f.code, f.successor from file_rows f where f.successor is not null
      union
      select w.start_row, w.start_code, e.successor
      from walk w
      join edges e on e.predecessor = w.node
      where w.node <> w.start_code
    )
    insert into ingest.pending_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value)
    select v_org, p_batch_id, p_file_no, f.row_no, 'successor_item_code', 'supersession_cycle', 'error', f.successor
    from file_rows f
    where exists (select 1 from walk w where w.start_row = f.row_no and w.node = w.start_code);
    get diagnostics v_n = row_count;
    v_found := v_found + v_n;
  end if;

  if v_entity = 'supplier_items' and 'is_preferred' = any (v_columns) then
    insert into ingest.pending_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value, detail)
    select v_org, p_batch_id, p_file_no, x.row_no, 'is_preferred', 'preferred_conflict', 'error', 'true',
           jsonb_build_object('first_row', x.first_row)
    from (
      select s.row_no, min(s.row_no) over (partition by s.cells[2]) as first_row
      from ingest.staged_rows s
      where s.organization_id = v_org and s.batch_id = p_batch_id and s.file_no = p_file_no and s.cells[10] = 'true'
    ) as x
    where x.row_no > x.first_row;
    get diagnostics v_n = row_count;
    v_found := v_found + v_n;
  end if;

  if v_entity = 'holiday_overrides' then
    with f as (
      select s.row_no,
             case when coalesce(s.cells[1], '') <> '' then 'country:' || s.cells[1]
                  when coalesce(s.cells[2], '') <> '' then 'calendar:' || s.cells[2] end as scope,
             case when s.cells[3] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(s.cells[3], 'date')
                  then s.cells[3]::date end as starts_on,
             case when s.cells[4] ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_catalog.pg_input_is_valid(s.cells[4], 'date')
                  then s.cells[4]::date end as ends_on
      from ingest.staged_rows s
      where s.organization_id = v_org and s.batch_id = p_batch_id and s.file_no = p_file_no
    ), fv as (
      select f.row_no, f.scope, daterange(f.starts_on, f.ends_on, '[]') as days, f.starts_on
      from f
      where f.scope is not null and f.starts_on is not null and f.ends_on is not null and f.ends_on >= f.starts_on
    ), stored as (
      select coalesce('calendar:' || w.code, 'country:' || h.country_code::text) as scope,
             daterange(h.starts_on, h.ends_on, '[]') as days, h.starts_on
      from public.holiday_overrides h
      left join public.work_calendars w on w.organization_id = h.organization_id and w.id = h.work_calendar_id
      where h.organization_id = v_org
    )
    insert into ingest.pending_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value)
    select v_org, p_batch_id, p_file_no, a.row_no, 'starts_on', 'holiday_overlap', 'error', a.starts_on::text
    from fv a
    where exists (select 1 from fv b where b.scope = a.scope and b.row_no < a.row_no and b.days && a.days)
       or exists (select 1 from stored t
                  where t.scope = a.scope and t.days && a.days
                    and not exists (select 1 from fv r where r.scope = t.scope and r.starts_on = t.starts_on));
    get diagnostics v_n = row_count;
    v_found := v_found + v_n;
  end if;

  return v_found;
end;
$$;

------------------------------------------------------------------------------------------------
-- Typed rows per entity: staged cells cast to the target types with lookups resolved. A provided
-- code that does not resolve becomes NULL in a NOT NULL column (23502) or the nil uuid in a
-- nullable foreign key (23503), so a reference that vanishes mid-commit fails loudly; the merge
-- functions also count unresolved rows first and raise MQ409 changed_during_commit.
------------------------------------------------------------------------------------------------

create or replace function app.import_rows_work_calendars(p_organization_id uuid, p_batch_id uuid, p_file_no smallint, p_from_row integer, p_to_row integer)
returns table (row_no integer, code text, name_en text, name_ar text, country_code char(2), weekend_days smallint[],
               observe_public_holidays boolean, is_active boolean)
language sql
stable
security definer
set search_path = ''
rows 5000
as $$
  select s.row_no, s.cells[1], s.cells[2], nullif(s.cells[3], ''), nullif(s.cells[4], '')::char(2),
         case when s.cells[5] is null then null
              when s.cells[5] = '' then '{}'::smallint[]
              else array(select d::smallint from unnest(string_to_array(s.cells[5], ';')) as d order by 1) end,
         s.cells[6]::boolean, s.cells[7]::boolean
  from ingest.staged_rows s
  where s.organization_id = p_organization_id and s.batch_id = p_batch_id and s.file_no = p_file_no
    and s.row_no between p_from_row and p_to_row;
$$;

create or replace function app.import_rows_holiday_overrides(p_organization_id uuid, p_batch_id uuid, p_file_no smallint, p_from_row integer, p_to_row integer)
returns table (row_no integer, country_code char(2), work_calendar_id uuid, scope_key text, starts_on date, ends_on date,
               kind text, name_en text, name_ar text, note text, unresolved boolean)
language sql
stable
security definer
set search_path = ''
rows 5000
as $$
  select s.row_no, nullif(s.cells[1], '')::char(2),
         case when nullif(s.cells[2], '') is null then null
              else coalesce(w.id, '00000000-0000-0000-0000-000000000000'::uuid) end,
         case when nullif(s.cells[1], '') is not null then 'country:' || s.cells[1]
              else 'calendar:' || coalesce(w.id::text, '-') end,
         s.cells[3]::date, s.cells[4]::date, s.cells[5], s.cells[6], nullif(s.cells[7], ''), nullif(s.cells[8], ''),
         nullif(s.cells[2], '') is not null and w.id is null
  from ingest.staged_rows s
  left join public.work_calendars w on w.organization_id = p_organization_id and w.code = nullif(s.cells[2], '')
  where s.organization_id = p_organization_id and s.batch_id = p_batch_id and s.file_no = p_file_no
    and s.row_no between p_from_row and p_to_row;
$$;

create or replace function app.import_rows_locations(p_organization_id uuid, p_batch_id uuid, p_file_no smallint, p_from_row integer, p_to_row integer)
returns table (row_no integer, code text, name_en text, name_ar text, location_type text, country_code char(2), city text,
               latitude numeric, longitude numeric, timezone text, parent_location_id uuid, is_active boolean,
               work_calendar_id uuid, parent_unresolved boolean, unresolved boolean)
language sql
stable
security definer
set search_path = ''
rows 5000
as $$
  select s.row_no, s.cells[1], s.cells[2], nullif(s.cells[3], ''), s.cells[4], s.cells[5]::char(2), nullif(s.cells[6], ''),
         nullif(s.cells[7], '')::numeric, nullif(s.cells[8], '')::numeric, s.cells[9],
         case when nullif(s.cells[10], '') is null then null
              else coalesce(p.id, '00000000-0000-0000-0000-000000000000'::uuid) end,
         s.cells[11]::boolean,
         case when nullif(s.cells[12], '') is null then null
              else coalesce(w.id, '00000000-0000-0000-0000-000000000000'::uuid) end,
         nullif(s.cells[10], '') is not null and p.id is null,
         nullif(s.cells[12], '') is not null and w.id is null
  from ingest.staged_rows s
  left join public.locations p on p.organization_id = p_organization_id and p.code = nullif(s.cells[10], '')
  left join public.work_calendars w on w.organization_id = p_organization_id and w.code = nullif(s.cells[12], '')
  where s.organization_id = p_organization_id and s.batch_id = p_batch_id and s.file_no = p_file_no
    and s.row_no between p_from_row and p_to_row;
$$;

