------------------------------------------------------------------------------------------------
-- Merges. Each: count unresolved references (MQ409 changed_during_commit), UPDATE existing rows
-- whose provided columns differ, INSERT new keys (unprovided columns get the table defaults,
-- written as literals) with ON CONFLICT absorbing a concurrent insert. Returns
-- {inserted, updated, unchanged, deleted, skipped}.
-- Every merge disables hash and merge joins: a unit has at most 5,000 (20,000 demand) staged rows,
-- each one natural-key probe of its target, while a hash join reads the whole target table, every
-- organization's rows (measured at 50,000 items of one organization: equally fast either way).
------------------------------------------------------------------------------------------------

create or replace function app.import_file_context(p_batch_id uuid, p_file_no smallint, p_entity text)
returns table (organization_id uuid, provided boolean[])
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  return query
    select f.organization_id, app.import_provided(f.entity, f.columns)
    from public.import_files f
    where f.batch_id = p_batch_id and f.file_no = p_file_no and f.entity = p_entity;
  if not found then
    raise exception 'import file % of batch % is not a % file', p_file_no, p_batch_id, p_entity;
  end if;
end;
$$;

create or replace function app.import_require_resolved(p_unresolved integer)
returns void
language plpgsql
immutable
security definer
set search_path = ''
as $$
begin
  if p_unresolved > 0 then
    raise exception using errcode = 'MQ409',
      message = format('%s rows refer to codes that no longer exist', p_unresolved),
      hint = 'changed_during_commit';
  end if;
end;
$$;

create or replace function app.import_merge_work_calendars(p_batch_id uuid, p_file_no smallint, p_from_row integer, p_to_row integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
set enable_hashjoin = off
set enable_mergejoin = off
as $$
declare
  v_org uuid;
  v_p boolean[];
  v_staged integer;
  v_updated integer;
  v_inserted integer;
  v_raced integer;
begin
  select c.organization_id, c.provided into v_org, v_p from app.import_file_context(p_batch_id, p_file_no, 'work_calendars') c;
  select count(*)::integer into v_staged from app.import_rows_work_calendars(v_org, p_batch_id, p_file_no, p_from_row, p_to_row);

  update public.work_calendars t
  set name_en = case when v_p[2] then x.name_en else t.name_en end,
      name_ar = case when v_p[3] then x.name_ar else t.name_ar end,
      country_code = case when v_p[4] then x.country_code else t.country_code end,
      weekend_days = case when v_p[5] then x.weekend_days else t.weekend_days end,
      observe_public_holidays = case when v_p[6] then x.observe_public_holidays else t.observe_public_holidays end,
      is_active = case when v_p[7] then x.is_active else t.is_active end
  from app.import_rows_work_calendars(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x
  where t.organization_id = v_org and t.code = x.code
    and ((v_p[2] and t.name_en is distinct from x.name_en)
      or (v_p[3] and t.name_ar is distinct from x.name_ar)
      or (v_p[4] and t.country_code is distinct from x.country_code)
      or (v_p[5] and t.weekend_days is distinct from x.weekend_days)
      or (v_p[6] and t.observe_public_holidays is distinct from x.observe_public_holidays)
      or (v_p[7] and t.is_active is distinct from x.is_active));
  get diagnostics v_updated = row_count;

  with ins as (
    insert into public.work_calendars as t (organization_id, code, name_en, name_ar, country_code, weekend_days, observe_public_holidays, is_active)
    select v_org, x.code, x.name_en, x.name_ar, x.country_code, coalesce(x.weekend_days, '{}'::smallint[]),
           coalesce(x.observe_public_holidays, true), coalesce(x.is_active, true)
    from app.import_rows_work_calendars(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x
    where not exists (select 1 from public.work_calendars e where e.organization_id = v_org and e.code = x.code)
    on conflict (organization_id, code) do update
    set name_en = case when v_p[2] then excluded.name_en else t.name_en end,
        name_ar = case when v_p[3] then excluded.name_ar else t.name_ar end,
        country_code = case when v_p[4] then excluded.country_code else t.country_code end,
        weekend_days = case when v_p[5] then excluded.weekend_days else t.weekend_days end,
        observe_public_holidays = case when v_p[6] then excluded.observe_public_holidays else t.observe_public_holidays end,
        is_active = case when v_p[7] then excluded.is_active else t.is_active end
    where (v_p[2] and t.name_en is distinct from excluded.name_en)
       or (v_p[3] and t.name_ar is distinct from excluded.name_ar)
       or (v_p[4] and t.country_code is distinct from excluded.country_code)
       or (v_p[5] and t.weekend_days is distinct from excluded.weekend_days)
       or (v_p[6] and t.observe_public_holidays is distinct from excluded.observe_public_holidays)
       or (v_p[7] and t.is_active is distinct from excluded.is_active)
    returning (t.xmax = 0) as fresh
  )
  select count(*) filter (where ins.fresh)::integer, count(*) filter (where not ins.fresh)::integer
    into v_inserted, v_raced
  from ins;

  return app.import_counts(v_staged, v_inserted, v_updated + v_raced, 0, 0);
end;
$$;

create or replace function app.import_merge_holiday_overrides(p_batch_id uuid, p_file_no smallint, p_from_row integer, p_to_row integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
set enable_hashjoin = off
set enable_mergejoin = off
as $$
declare
  v_org uuid;
  v_p boolean[];
  v_staged integer;
  v_unresolved integer;
  v_updated integer;
  v_inserted integer;
  v_raced integer;
begin
  select c.organization_id, c.provided into v_org, v_p from app.import_file_context(p_batch_id, p_file_no, 'holiday_overrides') c;
  select count(*)::integer, count(*) filter (where x.unresolved)::integer into v_staged, v_unresolved
  from app.import_rows_holiday_overrides(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x;
  perform app.import_require_resolved(v_unresolved);

  -- Updates first, then inserts: the no-overlap exclusion constraint is checked row by row.
  update public.holiday_overrides t
  set ends_on = case when v_p[4] then x.ends_on else t.ends_on end,
      kind = case when v_p[5] then x.kind else t.kind end,
      name_en = case when v_p[6] then x.name_en else t.name_en end,
      name_ar = case when v_p[7] then x.name_ar else t.name_ar end,
      note = case when v_p[8] then x.note else t.note end
  from app.import_rows_holiday_overrides(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x
  where t.organization_id = v_org and t.scope_key = x.scope_key and t.starts_on = x.starts_on
    and ((v_p[4] and t.ends_on is distinct from x.ends_on)
      or (v_p[5] and t.kind is distinct from x.kind)
      or (v_p[6] and t.name_en is distinct from x.name_en)
      or (v_p[7] and t.name_ar is distinct from x.name_ar)
      or (v_p[8] and t.note is distinct from x.note));
  get diagnostics v_updated = row_count;

  with ins as (
    insert into public.holiday_overrides as t (organization_id, work_calendar_id, country_code, starts_on, ends_on, kind, name_en, name_ar, note)
    select v_org, x.work_calendar_id, x.country_code, x.starts_on, x.ends_on, x.kind, x.name_en, x.name_ar, x.note
    from app.import_rows_holiday_overrides(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x
    where not exists (select 1 from public.holiday_overrides e
                      where e.organization_id = v_org and e.scope_key = x.scope_key and e.starts_on = x.starts_on)
    on conflict (organization_id, scope_key, starts_on) do update
    set ends_on = case when v_p[4] then excluded.ends_on else t.ends_on end,
        kind = case when v_p[5] then excluded.kind else t.kind end,
        name_en = case when v_p[6] then excluded.name_en else t.name_en end,
        name_ar = case when v_p[7] then excluded.name_ar else t.name_ar end,
        note = case when v_p[8] then excluded.note else t.note end
    where (v_p[4] and t.ends_on is distinct from excluded.ends_on)
       or (v_p[5] and t.kind is distinct from excluded.kind)
       or (v_p[6] and t.name_en is distinct from excluded.name_en)
       or (v_p[7] and t.name_ar is distinct from excluded.name_ar)
       or (v_p[8] and t.note is distinct from excluded.note)
    returning (t.xmax = 0) as fresh
  )
  select count(*) filter (where ins.fresh)::integer, count(*) filter (where not ins.fresh)::integer
    into v_inserted, v_raced
  from ins;

  return app.import_counts(v_staged, v_inserted, v_updated + v_raced, 0, 0);
end;
$$;

-- Locations, pass 1: every column except the parent (new rows start without one).
create or replace function app.import_merge_locations(p_batch_id uuid, p_file_no smallint, p_from_row integer, p_to_row integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
set enable_hashjoin = off
set enable_mergejoin = off
as $$
declare
  v_org uuid;
  v_p boolean[];
  v_staged integer;
  v_unresolved integer;
  v_updated integer;
  v_inserted integer;
  v_raced integer;
begin
  select c.organization_id, c.provided into v_org, v_p from app.import_file_context(p_batch_id, p_file_no, 'locations') c;
  select count(*)::integer, count(*) filter (where x.unresolved)::integer into v_staged, v_unresolved
  from app.import_rows_locations(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x;
  perform app.import_require_resolved(v_unresolved);

  update public.locations t
  set name_en = case when v_p[2] then x.name_en else t.name_en end,
      name_ar = case when v_p[3] then x.name_ar else t.name_ar end,
      location_type = case when v_p[4] then x.location_type else t.location_type end,
      country_code = case when v_p[5] then x.country_code else t.country_code end,
      city = case when v_p[6] then x.city else t.city end,
      latitude = case when v_p[7] then x.latitude else t.latitude end,
      longitude = case when v_p[8] then x.longitude else t.longitude end,
      timezone = case when v_p[9] then x.timezone else t.timezone end,
      is_active = case when v_p[11] then x.is_active else t.is_active end,
      work_calendar_id = case when v_p[12] then x.work_calendar_id else t.work_calendar_id end
  from app.import_rows_locations(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x
  where t.organization_id = v_org and t.code = x.code
    and ((v_p[2] and t.name_en is distinct from x.name_en)
      or (v_p[3] and t.name_ar is distinct from x.name_ar)
      or (v_p[4] and t.location_type is distinct from x.location_type)
      or (v_p[5] and t.country_code is distinct from x.country_code)
      or (v_p[6] and t.city is distinct from x.city)
      or (v_p[7] and t.latitude is distinct from x.latitude)
      or (v_p[8] and t.longitude is distinct from x.longitude)
      or (v_p[9] and t.timezone is distinct from x.timezone)
      or (v_p[11] and t.is_active is distinct from x.is_active)
      or (v_p[12] and t.work_calendar_id is distinct from x.work_calendar_id));
  get diagnostics v_updated = row_count;

  with ins as (
    insert into public.locations as t (organization_id, code, name_en, name_ar, location_type, country_code, city, latitude,
                                       longitude, timezone, is_active, work_calendar_id)
    select v_org, x.code, x.name_en, x.name_ar, x.location_type, x.country_code, x.city, x.latitude, x.longitude, x.timezone,
           coalesce(x.is_active, true), x.work_calendar_id
    from app.import_rows_locations(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x
    where not exists (select 1 from public.locations e where e.organization_id = v_org and e.code = x.code)
    on conflict (organization_id, code) do update
    set name_en = case when v_p[2] then excluded.name_en else t.name_en end,
        name_ar = case when v_p[3] then excluded.name_ar else t.name_ar end,
        location_type = case when v_p[4] then excluded.location_type else t.location_type end,
        country_code = case when v_p[5] then excluded.country_code else t.country_code end,
        city = case when v_p[6] then excluded.city else t.city end,
        latitude = case when v_p[7] then excluded.latitude else t.latitude end,
        longitude = case when v_p[8] then excluded.longitude else t.longitude end,
        timezone = case when v_p[9] then excluded.timezone else t.timezone end,
        is_active = case when v_p[11] then excluded.is_active else t.is_active end,
        work_calendar_id = case when v_p[12] then excluded.work_calendar_id else t.work_calendar_id end
    where (v_p[2] and t.name_en is distinct from excluded.name_en)
       or (v_p[3] and t.name_ar is distinct from excluded.name_ar)
       or (v_p[4] and t.location_type is distinct from excluded.location_type)
       or (v_p[5] and t.country_code is distinct from excluded.country_code)
       or (v_p[6] and t.city is distinct from excluded.city)
       or (v_p[7] and t.latitude is distinct from excluded.latitude)
       or (v_p[8] and t.longitude is distinct from excluded.longitude)
       or (v_p[9] and t.timezone is distinct from excluded.timezone)
       or (v_p[11] and t.is_active is distinct from excluded.is_active)
       or (v_p[12] and t.work_calendar_id is distinct from excluded.work_calendar_id)
    returning (t.xmax = 0) as fresh
  )
  select count(*) filter (where ins.fresh)::integer, count(*) filter (where not ins.fresh)::integer
    into v_inserted, v_raced
  from ins;

  return app.import_counts(v_staged, v_inserted, v_updated + v_raced, 0, 0);
end;
$$;

-- Locations, pass 2: parents, once every location of the file exists, so parents may appear
-- anywhere in the file and the cycle trigger sees the final rows. Returns {parents_set}.
create or replace function app.import_merge_location_parents(p_batch_id uuid, p_file_no smallint, p_from_row integer, p_to_row integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
set enable_hashjoin = off
set enable_mergejoin = off
as $$
declare
  v_org uuid;
  v_p boolean[];
  v_unresolved integer;
  v_updated integer;
begin
  select c.organization_id, c.provided into v_org, v_p from app.import_file_context(p_batch_id, p_file_no, 'locations') c;
  if not v_p[10] then
    return jsonb_build_object('parents_set', 0);
  end if;
  select count(*) filter (where x.parent_unresolved)::integer into v_unresolved
  from app.import_rows_locations(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x;
  perform app.import_require_resolved(v_unresolved);

  update public.locations t
  set parent_location_id = x.parent_location_id
  from app.import_rows_locations(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x
  where t.organization_id = v_org and t.code = x.code
    and t.parent_location_id is distinct from x.parent_location_id;
  get diagnostics v_updated = row_count;
  return jsonb_build_object('parents_set', v_updated);
end;
$$;

create or replace function app.import_merge_network_links(p_batch_id uuid, p_file_no smallint, p_from_row integer, p_to_row integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
set enable_hashjoin = off
set enable_mergejoin = off
as $$
declare
  v_org uuid;
  v_p boolean[];
  v_staged integer;
  v_unresolved integer;
  v_updated integer;
  v_inserted integer;
  v_raced integer;
