  from app.import_rows_network_links(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x;
  perform app.import_require_resolved(v_unresolved);

  update public.network_links t
  set lead_time_days_p50 = case when v_p[3] then x.lead_time_days_p50 else t.lead_time_days_p50 end,
      lead_time_days_p90 = case when v_p[4] then x.lead_time_days_p90 else t.lead_time_days_p90 end,
      freight_basis = case when v_p[5] then x.freight_basis else t.freight_basis end,
      freight_cost = case when v_p[6] then x.freight_cost else t.freight_cost end,
      currency = case when v_p[7] then x.currency else t.currency end,
