  where t.organization_id = v_org and t.from_location_id = x.from_location_id and t.to_location_id = x.to_location_id
    and ((v_p[3] and t.lead_time_days_p50 is distinct from x.lead_time_days_p50)
      or (v_p[4] and t.lead_time_days_p90 is distinct from x.lead_time_days_p90)
      or (v_p[5] and t.freight_basis is distinct from x.freight_basis)
      or (v_p[6] and t.freight_cost is distinct from x.freight_cost)
      or (v_p[7] and t.currency is distinct from x.currency)
      or (v_p[8] and t.is_active is distinct from x.is_active));
  get diagnostics v_updated = row_count;

  with ins as (
    insert into public.network_links as t (organization_id, from_location_id, to_location_id, lead_time_days_p50,
                                           lead_time_days_p90, freight_basis, freight_cost, currency, is_active)
    select v_org, x.from_location_id, x.to_location_id, x.lead_time_days_p50, x.lead_time_days_p90,
           coalesce(x.freight_basis, 'none'), x.freight_cost, x.currency, coalesce(x.is_active, true)
    from app.import_rows_network_links(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x
    where not exists (select 1 from public.network_links e
                      where e.organization_id = v_org and e.from_location_id = x.from_location_id
                        and e.to_location_id = x.to_location_id)
    on conflict (organization_id, from_location_id, to_location_id) do update
    set lead_time_days_p50 = case when v_p[3] then excluded.lead_time_days_p50 else t.lead_time_days_p50 end,
        lead_time_days_p90 = case when v_p[4] then excluded.lead_time_days_p90 else t.lead_time_days_p90 end,
        freight_basis = case when v_p[5] then excluded.freight_basis else t.freight_basis end,
        freight_cost = case when v_p[6] then excluded.freight_cost else t.freight_cost end,
        currency = case when v_p[7] then excluded.currency else t.currency end,
        is_active = case when v_p[8] then excluded.is_active else t.is_active end
    where (v_p[3] and t.lead_time_days_p50 is distinct from excluded.lead_time_days_p50)
       or (v_p[4] and t.lead_time_days_p90 is distinct from excluded.lead_time_days_p90)
       or (v_p[5] and t.freight_basis is distinct from excluded.freight_basis)
       or (v_p[6] and t.freight_cost is distinct from excluded.freight_cost)
       or (v_p[7] and t.currency is distinct from excluded.currency)
       or (v_p[8] and t.is_active is distinct from excluded.is_active)
    returning (t.xmax = 0) as fresh
  )
  select count(*) filter (where ins.fresh)::integer, count(*) filter (where not ins.fresh)::integer
    into v_inserted, v_raced
  from ins;

  return app.import_counts(v_staged, v_inserted, v_updated + v_raced, 0, 0);
end;
$$;

