-- The predecessor is the key: an import replaces the successor.
create or replace function app.import_merge_item_supersessions(p_batch_id uuid, p_file_no smallint, p_from_row integer, p_to_row integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
set enable_hashjoin = off
set enable_mergejoin = off
as $$
declare
  v_org uuid;
  v_p boolean[];
  v_staged integer;
  v_unresolved integer;
  v_updated integer;
  v_inserted integer;
  v_raced integer;
begin
  select c.organization_id, c.provided into v_org, v_p from app.import_file_context(p_batch_id, p_file_no, 'item_supersessions') c;
  select count(*)::integer, count(*) filter (where x.unresolved)::integer into v_staged, v_unresolved
  from app.import_rows_item_supersessions(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x;
  perform app.import_require_resolved(v_unresolved);

  update public.item_supersessions t
  set successor_item_id = case when v_p[2] then x.successor_item_id else t.successor_item_id end,
      effective_on = case when v_p[3] then x.effective_on else t.effective_on end,
      quantity_factor = case when v_p[4] then x.quantity_factor else t.quantity_factor end,
      note = case when v_p[5] then x.note else t.note end
  from app.import_rows_item_supersessions(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x
  where t.organization_id = v_org and t.predecessor_item_id = x.predecessor_item_id
    and ((v_p[2] and t.successor_item_id is distinct from x.successor_item_id)
      or (v_p[3] and t.effective_on is distinct from x.effective_on)
      or (v_p[4] and t.quantity_factor is distinct from x.quantity_factor)
      or (v_p[5] and t.note is distinct from x.note));
  get diagnostics v_updated = row_count;

  with ins as (
    insert into public.item_supersessions as t (organization_id, predecessor_item_id, successor_item_id, effective_on, quantity_factor, note)
    select v_org, x.predecessor_item_id, x.successor_item_id, x.effective_on, coalesce(x.quantity_factor, 1), x.note
    from app.import_rows_item_supersessions(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x
    where not exists (select 1 from public.item_supersessions e
                      where e.organization_id = v_org and e.predecessor_item_id = x.predecessor_item_id)
    on conflict (organization_id, predecessor_item_id) do update
    set successor_item_id = case when v_p[2] then excluded.successor_item_id else t.successor_item_id end,
        effective_on = case when v_p[3] then excluded.effective_on else t.effective_on end,
        quantity_factor = case when v_p[4] then excluded.quantity_factor else t.quantity_factor end,
        note = case when v_p[5] then excluded.note else t.note end
    where (v_p[2] and t.successor_item_id is distinct from excluded.successor_item_id)
       or (v_p[3] and t.effective_on is distinct from excluded.effective_on)
       or (v_p[4] and t.quantity_factor is distinct from excluded.quantity_factor)
       or (v_p[5] and t.note is distinct from excluded.note)
    returning (t.xmax = 0) as fresh
  )
  select count(*) filter (where ins.fresh)::integer, count(*) filter (where not ins.fresh)::integer
    into v_inserted, v_raced
  from ins;

  return app.import_counts(v_staged, v_inserted, v_updated + v_raced, 0, 0);
end;
$$;

-- One row per unordered pair. The file's orientation replaces the stored one only when the file
-- maps direction (the value that depends on it); otherwise the stored orientation and direction
-- stay, so a reversed pair cannot silently turn a one-way substitution around.
create or replace function app.import_merge_item_interchanges(p_batch_id uuid, p_file_no smallint, p_from_row integer, p_to_row integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
set enable_hashjoin = off
set enable_mergejoin = off
as $$
declare
  v_org uuid;
  v_p boolean[];
  v_staged integer;
  v_unresolved integer;
  v_updated integer;
  v_inserted integer;
  v_raced integer;
begin
  select c.organization_id, c.provided into v_org, v_p from app.import_file_context(p_batch_id, p_file_no, 'item_interchanges') c;
  select count(*)::integer, count(*) filter (where x.unresolved)::integer into v_staged, v_unresolved
  from app.import_rows_item_interchanges(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x;
  perform app.import_require_resolved(v_unresolved);

  update public.item_interchanges t
  set item_id = case when v_p[3] then x.item_id else t.item_id end,
      alternate_item_id = case when v_p[3] then x.alternate_item_id else t.alternate_item_id end,
      direction = case when v_p[3] then x.direction else t.direction end,
      priority = case when v_p[4] then x.priority else t.priority end,
      note = case when v_p[5] then x.note else t.note end
  from app.import_rows_item_interchanges(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x
  where t.organization_id = v_org
    and least(t.item_id, t.alternate_item_id) = least(x.item_id, x.alternate_item_id)
    and greatest(t.item_id, t.alternate_item_id) = greatest(x.item_id, x.alternate_item_id)
    and ((v_p[3] and t.item_id is distinct from x.item_id)
      or (v_p[3] and t.direction is distinct from x.direction)
      or (v_p[4] and t.priority is distinct from x.priority)
      or (v_p[5] and t.note is distinct from x.note));
  get diagnostics v_updated = row_count;

  with ins as (
    insert into public.item_interchanges as t (organization_id, item_id, alternate_item_id, direction, priority, note)
    select v_org, x.item_id, x.alternate_item_id, coalesce(x.direction, 'two_way'), coalesce(x.priority, 1::smallint), x.note
    from app.import_rows_item_interchanges(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x
    where not exists (select 1 from public.item_interchanges e
                      where e.organization_id = v_org
                        and least(e.item_id, e.alternate_item_id) = least(x.item_id, x.alternate_item_id)
                        and greatest(e.item_id, e.alternate_item_id) = greatest(x.item_id, x.alternate_item_id))
    on conflict (organization_id, least(item_id, alternate_item_id), greatest(item_id, alternate_item_id)) do update
    set item_id = case when v_p[3] then excluded.item_id else t.item_id end,
        alternate_item_id = case when v_p[3] then excluded.alternate_item_id else t.alternate_item_id end,
        direction = case when v_p[3] then excluded.direction else t.direction end,
        priority = case when v_p[4] then excluded.priority else t.priority end,
        note = case when v_p[5] then excluded.note else t.note end
    where (v_p[3] and t.item_id is distinct from excluded.item_id)
       or (v_p[3] and t.direction is distinct from excluded.direction)
       or (v_p[4] and t.priority is distinct from excluded.priority)
       or (v_p[5] and t.note is distinct from excluded.note)
    returning (t.xmax = 0) as fresh
  )
  select count(*) filter (where ins.fresh)::integer, count(*) filter (where not ins.fresh)::integer
    into v_inserted, v_raced
  from ins;

  return app.import_counts(v_staged, v_inserted, v_updated + v_raced, 0, 0);
end;
$$;

create or replace function app.import_merge_suppliers(p_batch_id uuid, p_file_no smallint, p_from_row integer, p_to_row integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
set enable_hashjoin = off
set enable_mergejoin = off
as $$
declare
  v_org uuid;
  v_p boolean[];
  v_staged integer;
  v_unresolved integer;
  v_updated integer;
  v_inserted integer;
  v_raced integer;
begin
  select c.organization_id, c.provided into v_org, v_p from app.import_file_context(p_batch_id, p_file_no, 'suppliers') c;
  select count(*)::integer, count(*) filter (where x.unresolved)::integer into v_staged, v_unresolved
  from app.import_rows_suppliers(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x;
  perform app.import_require_resolved(v_unresolved);

  update public.suppliers t
  set name_en = case when v_p[2] then x.name_en else t.name_en end,
      name_ar = case when v_p[3] then x.name_ar else t.name_ar end,
      country_code = case when v_p[4] then x.country_code else t.country_code end,
      currency = case when v_p[5] then x.currency else t.currency end,
      lead_time_days_p50 = case when v_p[6] then x.lead_time_days_p50 else t.lead_time_days_p50 end,
      lead_time_days_p90 = case when v_p[7] then x.lead_time_days_p90 else t.lead_time_days_p90 end,
      is_active = case when v_p[8] then x.is_active else t.is_active end,
      work_calendar_id = case when v_p[9] then x.work_calendar_id else t.work_calendar_id end
  from app.import_rows_suppliers(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x
  where t.organization_id = v_org and t.code = x.code
    and ((v_p[2] and t.name_en is distinct from x.name_en)
      or (v_p[3] and t.name_ar is distinct from x.name_ar)
      or (v_p[4] and t.country_code is distinct from x.country_code)
      or (v_p[5] and t.currency is distinct from x.currency)
      or (v_p[6] and t.lead_time_days_p50 is distinct from x.lead_time_days_p50)
      or (v_p[7] and t.lead_time_days_p90 is distinct from x.lead_time_days_p90)
      or (v_p[8] and t.is_active is distinct from x.is_active)
      or (v_p[9] and t.work_calendar_id is distinct from x.work_calendar_id));
  get diagnostics v_updated = row_count;

  with ins as (
    insert into public.suppliers as t (organization_id, code, name_en, name_ar, country_code, currency, lead_time_days_p50,
                                       lead_time_days_p90, is_active, work_calendar_id)
    select v_org, x.code, x.name_en, x.name_ar, x.country_code, x.currency, x.lead_time_days_p50, x.lead_time_days_p90,
           coalesce(x.is_active, true), x.work_calendar_id
    from app.import_rows_suppliers(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x
    where not exists (select 1 from public.suppliers e where e.organization_id = v_org and e.code = x.code)
    on conflict (organization_id, code) do update
    set name_en = case when v_p[2] then excluded.name_en else t.name_en end,
        name_ar = case when v_p[3] then excluded.name_ar else t.name_ar end,
        country_code = case when v_p[4] then excluded.country_code else t.country_code end,
        currency = case when v_p[5] then excluded.currency else t.currency end,
        lead_time_days_p50 = case when v_p[6] then excluded.lead_time_days_p50 else t.lead_time_days_p50 end,
        lead_time_days_p90 = case when v_p[7] then excluded.lead_time_days_p90 else t.lead_time_days_p90 end,
        is_active = case when v_p[8] then excluded.is_active else t.is_active end,
        work_calendar_id = case when v_p[9] then excluded.work_calendar_id else t.work_calendar_id end
    where (v_p[2] and t.name_en is distinct from excluded.name_en)
       or (v_p[3] and t.name_ar is distinct from excluded.name_ar)
       or (v_p[4] and t.country_code is distinct from excluded.country_code)
       or (v_p[5] and t.currency is distinct from excluded.currency)
       or (v_p[6] and t.lead_time_days_p50 is distinct from excluded.lead_time_days_p50)
       or (v_p[7] and t.lead_time_days_p90 is distinct from excluded.lead_time_days_p90)
       or (v_p[8] and t.is_active is distinct from excluded.is_active)
       or (v_p[9] and t.work_calendar_id is distinct from excluded.work_calendar_id)
    returning (t.xmax = 0) as fresh
  )
  select count(*) filter (where ins.fresh)::integer, count(*) filter (where not ins.fresh)::integer
    into v_inserted, v_raced
  from ins;

  return app.import_counts(v_staged, v_inserted, v_updated + v_raced, 0, 0);
end;
$$;

-- A preferred row clears the item's other preferred rows first (one preferred supplier per item).
create or replace function app.import_merge_supplier_items(p_batch_id uuid, p_file_no smallint, p_from_row integer, p_to_row integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
set enable_hashjoin = off
set enable_mergejoin = off
as $$
declare
  v_org uuid;
  v_p boolean[];
  v_staged integer;
  v_unresolved integer;
  v_cleared integer := 0;
  v_updated integer;
  v_inserted integer;
  v_raced integer;
begin
  select c.organization_id, c.provided into v_org, v_p from app.import_file_context(p_batch_id, p_file_no, 'supplier_items') c;
  select count(*)::integer, count(*) filter (where x.unresolved)::integer into v_staged, v_unresolved
  from app.import_rows_supplier_items(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x;
  perform app.import_require_resolved(v_unresolved);

  if v_p[10] then
    update public.supplier_items t
    set is_preferred = false
    from app.import_rows_supplier_items(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x
    where x.is_preferred
      and t.organization_id = v_org and t.item_id = x.item_id and t.supplier_id <> x.supplier_id and t.is_preferred;
    get diagnostics v_cleared = row_count;
  end if;

  update public.supplier_items t
  set supplier_part_number = case when v_p[3] then x.supplier_part_number else t.supplier_part_number end,
      lead_time_days = case when v_p[4] then x.lead_time_days else t.lead_time_days end,
      lead_time_days_p90 = case when v_p[5] then x.lead_time_days_p90 else t.lead_time_days_p90 end,
      min_order_quantity = case when v_p[6] then x.min_order_quantity else t.min_order_quantity end,
      pack_size = case when v_p[7] then x.pack_size else t.pack_size end,
      unit_price = case when v_p[8] then x.unit_price else t.unit_price end,
      currency = case when v_p[9] then x.currency else t.currency end,
      is_preferred = case when v_p[10] then x.is_preferred else t.is_preferred end,
      valid_from = case when v_p[11] then x.valid_from else t.valid_from end
  from app.import_rows_supplier_items(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x
  where t.organization_id = v_org and t.supplier_id = x.supplier_id and t.item_id = x.item_id
    and ((v_p[3] and t.supplier_part_number is distinct from x.supplier_part_number)
      or (v_p[4] and t.lead_time_days is distinct from x.lead_time_days)
      or (v_p[5] and t.lead_time_days_p90 is distinct from x.lead_time_days_p90)
      or (v_p[6] and t.min_order_quantity is distinct from x.min_order_quantity)
      or (v_p[7] and t.pack_size is distinct from x.pack_size)
      or (v_p[8] and t.unit_price is distinct from x.unit_price)
      or (v_p[9] and t.currency is distinct from x.currency)
      or (v_p[10] and t.is_preferred is distinct from x.is_preferred)
      or (v_p[11] and t.valid_from is distinct from x.valid_from));
  get diagnostics v_updated = row_count;

  with ins as (
    insert into public.supplier_items as t (organization_id, supplier_id, item_id, supplier_part_number, lead_time_days,
                                            lead_time_days_p90, min_order_quantity, pack_size, unit_price, currency,
                                            is_preferred, valid_from)
    select v_org, x.supplier_id, x.item_id, x.supplier_part_number, x.lead_time_days, x.lead_time_days_p90,
           coalesce(x.min_order_quantity, 0), coalesce(x.pack_size, 1), x.unit_price, x.currency,
           coalesce(x.is_preferred, false), x.valid_from
    from app.import_rows_supplier_items(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x
    where not exists (select 1 from public.supplier_items e
                      where e.organization_id = v_org and e.supplier_id = x.supplier_id and e.item_id = x.item_id)
    on conflict (organization_id, supplier_id, item_id) do update
    set supplier_part_number = case when v_p[3] then excluded.supplier_part_number else t.supplier_part_number end,
        lead_time_days = case when v_p[4] then excluded.lead_time_days else t.lead_time_days end,
        lead_time_days_p90 = case when v_p[5] then excluded.lead_time_days_p90 else t.lead_time_days_p90 end,
        min_order_quantity = case when v_p[6] then excluded.min_order_quantity else t.min_order_quantity end,
        pack_size = case when v_p[7] then excluded.pack_size else t.pack_size end,
        unit_price = case when v_p[8] then excluded.unit_price else t.unit_price end,
        currency = case when v_p[9] then excluded.currency else t.currency end,
        is_preferred = case when v_p[10] then excluded.is_preferred else t.is_preferred end,
        valid_from = case when v_p[11] then excluded.valid_from else t.valid_from end
    where (v_p[3] and t.supplier_part_number is distinct from excluded.supplier_part_number)
       or (v_p[4] and t.lead_time_days is distinct from excluded.lead_time_days)
       or (v_p[5] and t.lead_time_days_p90 is distinct from excluded.lead_time_days_p90)
       or (v_p[6] and t.min_order_quantity is distinct from excluded.min_order_quantity)
       or (v_p[7] and t.pack_size is distinct from excluded.pack_size)
       or (v_p[8] and t.unit_price is distinct from excluded.unit_price)
       or (v_p[9] and t.currency is distinct from excluded.currency)
       or (v_p[10] and t.is_preferred is distinct from excluded.is_preferred)
       or (v_p[11] and t.valid_from is distinct from excluded.valid_from)
    returning (t.xmax = 0) as fresh
  )
  select count(*) filter (where ins.fresh)::integer, count(*) filter (where not ins.fresh)::integer
    into v_inserted, v_raced
  from ins;

  return app.import_counts(v_staged, v_inserted, v_updated + v_raced, 0, 0)
    || jsonb_build_object('preferred_cleared', v_cleared);
end;
$$;

-- One row per unordered currency pair and date. The file's orientation replaces the stored one only
-- when the file maps rate (which means something only in its orientation); otherwise the stored
-- orientation and rate stay, so a reversed pair cannot silently invert a rate.
create or replace function app.import_merge_fx_rates(p_batch_id uuid, p_file_no smallint, p_from_row integer, p_to_row integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
set enable_hashjoin = off
set enable_mergejoin = off
as $$
declare
  v_org uuid;
  v_p boolean[];
  v_staged integer;
  v_updated integer;
  v_inserted integer;
  v_raced integer;
begin
  select c.organization_id, c.provided into v_org, v_p from app.import_file_context(p_batch_id, p_file_no, 'fx_rates') c;
  select count(*)::integer into v_staged from app.import_rows_fx_rates(v_org, p_batch_id, p_file_no, p_from_row, p_to_row);

  update public.fx_rates t
  set from_currency = case when v_p[4] then x.from_currency else t.from_currency end,
      to_currency = case when v_p[4] then x.to_currency else t.to_currency end,
      rate = case when v_p[4] then x.rate else t.rate end,
      note = case when v_p[5] then x.note else t.note end
  from app.import_rows_fx_rates(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x
  where t.organization_id = v_org
    and least(t.from_currency, t.to_currency) = least(x.from_currency, x.to_currency)
    and greatest(t.from_currency, t.to_currency) = greatest(x.from_currency, x.to_currency)
    and t.valid_from = x.valid_from
    and ((v_p[4] and t.from_currency is distinct from x.from_currency)
      or (v_p[4] and t.rate is distinct from x.rate)
      or (v_p[5] and t.note is distinct from x.note));
  get diagnostics v_updated = row_count;

  with ins as (
    insert into public.fx_rates as t (organization_id, from_currency, to_currency, valid_from, rate, note)
    select v_org, x.from_currency, x.to_currency, x.valid_from, x.rate, x.note
    from app.import_rows_fx_rates(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x
    where not exists (select 1 from public.fx_rates e
                      where e.organization_id = v_org
                        and least(e.from_currency, e.to_currency) = least(x.from_currency, x.to_currency)
                        and greatest(e.from_currency, e.to_currency) = greatest(x.from_currency, x.to_currency)
                        and e.valid_from = x.valid_from)
    on conflict (organization_id, least(from_currency, to_currency), greatest(from_currency, to_currency), valid_from) do update
    set from_currency = case when v_p[4] then excluded.from_currency else t.from_currency end,
        to_currency = case when v_p[4] then excluded.to_currency else t.to_currency end,
        rate = case when v_p[4] then excluded.rate else t.rate end,
        note = case when v_p[5] then excluded.note else t.note end
    where (v_p[4] and t.from_currency is distinct from excluded.from_currency)
       or (v_p[4] and t.rate is distinct from excluded.rate)
       or (v_p[5] and t.note is distinct from excluded.note)
    returning (t.xmax = 0) as fresh
  )
  select count(*) filter (where ins.fresh)::integer, count(*) filter (where not ins.fresh)::integer
    into v_inserted, v_raced
  from ins;

  return app.import_counts(v_staged, v_inserted, v_updated + v_raced, 0, 0);
end;
$$;

-- Demand: one MERGE. Provided quantities replace the stored ones, unprovided ones are kept; a row
-- whose resulting quantities are both 0 deletes the day, and is skipped (counted) when the key does
-- not exist. Every import step writing demand holds maqdar.import:<org>, so MERGE cannot race
-- another import (a direct write through the editor policies surfaces as 23505 ->
-- concurrent_change); nested loops without materialization, over freshly analyzed partitions, keep each source
-- row a single primary-key probe in its month partition. MERGE was timed against DELETE + UPDATE
-- + INSERT ... ON CONFLICT on 20,000 rows: about the same for inserts, twice as fast unchanged.
create or replace function app.import_merge_demand_history(p_batch_id uuid, p_file_no smallint, p_from_row integer, p_to_row integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
set enable_hashjoin = off
set enable_mergejoin = off
set enable_material = off
as $$
declare
  v_org uuid;
  v_p boolean[];
  v_staged integer;
  v_unresolved integer;
  v_skipped integer;
  v_first date;
  v_last date;
  v_inserted integer;
  v_updated integer;
  v_deleted integer;
begin
  select c.organization_id, c.provided into v_org, v_p from app.import_file_context(p_batch_id, p_file_no, 'demand_history') c;
  select count(*)::integer, count(*) filter (where x.unresolved)::integer, min(x.demand_date), max(x.demand_date),
         count(*) filter (where coalesce(x.quantity, 0) = 0 and coalesce(x.lost_sales_quantity, 0) = 0
                            and not exists (select 1 from public.demand_history d
                                            where d.organization_id = v_org and d.item_id = x.item_id
                                              and d.location_id = x.location_id and d.demand_date = x.demand_date))::integer
    into v_staged, v_unresolved, v_first, v_last, v_skipped
  from app.import_rows_demand_history(v_org, p_batch_id, p_file_no, p_from_row, p_to_row) x;
  perform app.import_require_resolved(v_unresolved);
  if v_staged = 0 then
    return app.import_counts(0, 0, 0, 0, 0);
  end if;
  perform app.import_analyze_demand_months(v_first, v_last);

  with m as (
    merge into public.demand_history t
    using (select * from app.import_rows_demand_history(v_org, p_batch_id, p_file_no, p_from_row, p_to_row)) x
    on t.organization_id = v_org and t.item_id = x.item_id and t.location_id = x.location_id
       and t.demand_date = x.demand_date and t.demand_date between v_first and v_last
    when matched and coalesce(x.quantity, t.quantity) = 0 and coalesce(x.lost_sales_quantity, t.lost_sales_quantity) = 0 then
      delete
    when matched and (coalesce(x.quantity, t.quantity) <> t.quantity
                      or coalesce(x.lost_sales_quantity, t.lost_sales_quantity) <> t.lost_sales_quantity) then
      update set quantity = coalesce(x.quantity, t.quantity),
                 lost_sales_quantity = coalesce(x.lost_sales_quantity, t.lost_sales_quantity)
    when not matched and (coalesce(x.quantity, 0) > 0 or coalesce(x.lost_sales_quantity, 0) > 0) then
      insert (organization_id, item_id, location_id, demand_date, quantity, lost_sales_quantity)
      values (v_org, x.item_id, x.location_id, x.demand_date, coalesce(x.quantity, 0), coalesce(x.lost_sales_quantity, 0))
    returning merge_action() as action
  )
  select count(*) filter (where m.action = 'INSERT')::integer,
         count(*) filter (where m.action = 'UPDATE')::integer,
         count(*) filter (where m.action = 'DELETE')::integer
    into v_inserted, v_updated, v_deleted
  from m;

  return app.import_counts(v_staged, v_inserted, v_updated, v_deleted, v_skipped);
end;
$$;

create or replace function app.import_merge_unit(p_batch_id uuid, p_file_no smallint, p_entity text, p_from_row integer, p_to_row integer, p_pass integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  return case p_entity
    when 'work_calendars' then app.import_merge_work_calendars(p_batch_id, p_file_no, p_from_row, p_to_row)
    when 'holiday_overrides' then app.import_merge_holiday_overrides(p_batch_id, p_file_no, p_from_row, p_to_row)
    when 'locations' then case when p_pass = 2
      then app.import_merge_location_parents(p_batch_id, p_file_no, p_from_row, p_to_row)
      else app.import_merge_locations(p_batch_id, p_file_no, p_from_row, p_to_row) end
    when 'network_links' then app.import_merge_network_links(p_batch_id, p_file_no, p_from_row, p_to_row)
    when 'brands' then app.import_merge_brands(p_batch_id, p_file_no, p_from_row, p_to_row)
    when 'items' then app.import_merge_items(p_batch_id, p_file_no, p_from_row, p_to_row)
    when 'item_supersessions' then app.import_merge_item_supersessions(p_batch_id, p_file_no, p_from_row, p_to_row)
    when 'item_interchanges' then app.import_merge_item_interchanges(p_batch_id, p_file_no, p_from_row, p_to_row)
    when 'suppliers' then app.import_merge_suppliers(p_batch_id, p_file_no, p_from_row, p_to_row)
    when 'supplier_items' then app.import_merge_supplier_items(p_batch_id, p_file_no, p_from_row, p_to_row)
    when 'fx_rates' then app.import_merge_fx_rates(p_batch_id, p_file_no, p_from_row, p_to_row)
    when 'demand_history' then app.import_merge_demand_history(p_batch_id, p_file_no, p_from_row, p_to_row)
  end;
end;
$$;

------------------------------------------------------------------------------------------------
-- Commit support
------------------------------------------------------------------------------------------------

-- The failure code of a merge unit from the error it raised.
create or replace function app.import_failure_code(p_sqlstate text, p_hint text, p_constraint text)
returns text
language sql
immutable
security definer
set search_path = ''
as $$
  select case
    when p_sqlstate = 'MQ409' and p_hint = 'changed_during_commit' then 'changed_during_commit'
    when p_sqlstate = 'MQ422' and p_hint = 'successor_item_code' then 'supersession_cycle'
    when p_sqlstate = 'MQ422' and p_hint = 'parent_location_id' then 'location_cycle'
    when p_sqlstate = '23P01' then 'holiday_overlap'
    when p_sqlstate = '23505' and p_constraint = 'supplier_items_one_preferred_key' then 'preferred_conflict'
    when p_sqlstate in ('23502', '23503') then 'changed_during_commit'
    else 'concurrent_change'
  end;
$$;

-- Target tables an import writes or looks codes up in (never the demand_history parent).
create or replace function app.import_batch_tables(p_batch_id uuid)
returns text[]
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(array_agg(distinct s.entity order by s.entity), '{}'::text[])
  from (
    select f.entity from public.import_files f where f.batch_id = p_batch_id
    union
    select c.lookup_entity
    from public.import_files f
    join ingest.contract_columns c on c.entity = f.entity and c.lookup_entity is not null
    where f.batch_id = p_batch_id
  ) as s
  where s.entity <> 'demand_history';
$$;

-- ANALYZE the target tables whose statistics look stale (never analyzed but not empty, grown by
-- more than 20 % since the last analyze, or more than 10 % modified) or of which this batch inserted
-- more than 10 %. Merges and reference checks join on these tables; stale statistics once turned a
-- 14 s load into 724 s. The size check needs no pgstat flush, which lags a commit by seconds.
create or replace function app.import_prepare_stats(p_batch_id uuid, p_entities text[])
returns text[]
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_entity text;
  v_reltuples real;
  v_relpages integer;
  v_pages bigint;
  v_modified bigint;
  v_inserted bigint;
  v_counts jsonb;
  v_done text[] := '{}';
begin
  select b.counts into v_counts from public.import_batches b where b.id = p_batch_id;
  for v_entity in
    select distinct x from unnest(p_entities) as x
    where x in ('work_calendars', 'holiday_overrides', 'locations', 'network_links', 'brands', 'items', 'item_supersessions',
                'item_interchanges', 'suppliers', 'supplier_items', 'fx_rates')
    order by 1
  loop
    select c.reltuples, c.relpages, coalesce(s.n_mod_since_analyze, 0),
           pg_catalog.pg_relation_size(c.oid) / current_setting('block_size')::integer
      into v_reltuples, v_relpages, v_modified, v_pages
    from pg_catalog.pg_class c
    left join pg_catalog.pg_stat_user_tables s on s.relid = c.oid
    where c.oid = pg_catalog.to_regclass('public.' || v_entity);
    v_inserted := coalesce((v_counts -> v_entity ->> 'inserted')::bigint, 0);
    if (v_reltuples <= 0 and v_pages > 0)
       or v_pages > v_relpages * 1.2 + 8
       or v_modified > 0.1 * greatest(v_reltuples, 0)
       or v_inserted > 0.1 * greatest(v_reltuples, 0) then
      case v_entity
        when 'work_calendars' then analyze public.work_calendars;
        when 'holiday_overrides' then analyze public.holiday_overrides;
        when 'locations' then analyze public.locations;
        when 'network_links' then analyze public.network_links;
        when 'brands' then analyze public.brands;
        when 'items' then analyze public.items;
        when 'item_supersessions' then analyze public.item_supersessions;
        when 'item_interchanges' then analyze public.item_interchanges;
        when 'suppliers' then analyze public.suppliers;
        when 'supplier_items' then analyze public.supplier_items;
        when 'fx_rates' then analyze public.fx_rates;
      end case;
      v_done := v_done || ('public.' || v_entity);
    end if;
  end loop;
  return v_done;
end;
$$;

-- ANALYZE the demand partitions overlapping [p_first, p_last] whose statistics are stale (never
-- analyzed but not empty, or grown by more than 20 % since the last analyze). Demand probes and the
-- MERGE join on one month partition; with a stale partition (say 21,000 rows that the statistics
-- still count as none) the planner reads the organization's whole month once per source row
-- (measured: 21 s for 20,000 unchanged rows, 0.7 s once analyzed). Never the 96-partition parent.
-- The partition names come from the catalog (regclass), never from input.
create or replace function app.import_analyze_demand_months(p_first date, p_last date)
returns text[]
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_partition regclass;
  v_done text[] := '{}';
begin
  if p_first is null or p_last is null then
    return v_done;
  end if;
  for v_partition in
    select c.oid::regclass
    from pg_catalog.pg_inherits i
    join pg_catalog.pg_class c on c.oid = i.inhrelid
    cross join lateral regexp_match(
      pg_catalog.pg_get_expr(c.relpartbound, c.oid),
      'FROM \(''([0-9]{4}-[0-9]{2}-[0-9]{2})''\) TO \(''([0-9]{4}-[0-9]{2}-[0-9]{2})''\)') as m
    where i.inhparent = 'public.demand_history'::regclass
      and m[1]::date <= p_last and m[2]::date > p_first
      and pg_catalog.pg_relation_size(c.oid) > 0
      and (c.reltuples < 0
           or pg_catalog.pg_relation_size(c.oid) / current_setting('block_size')::integer > c.relpages * 1.2 + 8)
    order by 1
  loop
    execute format('analyze %s', v_partition);
    v_done := v_done || v_partition::text;
  end loop;
  return v_done;
end;
$$;

-- Deletes up to p_max_rows staged rows of a batch; once none are left, its chunks and pending
-- errors too, and records staging_cleared_at. Returns the rows deleted.
create or replace function app.import_drop_staging(p_batch_id uuid, p_max_rows integer)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_n integer;
begin
  delete from ingest.staged_rows s
  where s.batch_id = p_batch_id
    and (s.file_no, s.row_no) in (
      select r.file_no, r.row_no from ingest.staged_rows r
      where r.batch_id = p_batch_id
      limit greatest(p_max_rows, 0));
  get diagnostics v_n = row_count;
  if v_n < p_max_rows then
    delete from ingest.staged_chunks c where c.batch_id = p_batch_id;
    delete from ingest.pending_errors e where e.batch_id = p_batch_id;
    update public.import_batches b set staging_cleared_at = now()
    where b.id = p_batch_id and b.staging_cleared_at is null;
  end if;
  return v_n;
end;
$$;

-- Housekeeping without cron, in small slices: expire open batches idle for 24 hours, fail
-- commits without a step for 30 minutes (freeing the committing slot), and delete the staging rows
-- of finished batches (at most p_max_rows, capped at 20,000, per call). p_except is the batch the
-- caller is about to act on: a commit step that continues its own idle commit must not fail it
-- first (the step would then refuse the failed batch and roll the sweep back with it, leaving the
-- batch stuck in committing).
create or replace function app.import_sweep(p_max_rows integer, p_except uuid default null)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_budget integer := least(greatest(coalesce(p_max_rows, 0), 0), 20000);
  v_deleted integer := 0;
  v_batch uuid;
begin
  update public.import_batches b
  set status = 'expired', finished_at = now()
  where b.id in (
    select x.id from public.import_batches x
    where x.status in ('staging', 'validated', 'invalid', 'failed') and x.expires_at < now()
      and x.id is distinct from p_except
    order by x.expires_at
    limit 100
    for update skip locked);

  update public.import_batches b
  set status = 'failed', failure_code = 'abandoned', failure_detail = 'no commit step for 30 minutes',
      expires_at = now() + interval '24 hours'
  where b.id in (
    select x.id from public.import_batches x
    where x.status = 'committing' and x.last_step_at < now() - interval '30 minutes'
      and x.id is distinct from p_except
    limit 100
    for update skip locked);

  if v_budget > 0 then
    for v_batch in
      select x.id from public.import_batches x
      where x.staging_cleared_at is null and x.status in ('succeeded', 'canceled', 'expired')
      order by x.finished_at
      limit 20
      for update skip locked
    loop
      exit when v_deleted >= v_budget;
      v_deleted := v_deleted + app.import_drop_staging(v_batch, v_budget - v_deleted);
    end loop;
  end if;
  return v_deleted;
end;
$$;

-- Deleting batches (including through an organization delete) drops their staging rows.
create or replace function app.import_batches_drop_staging()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  delete from ingest.staged_rows s where s.batch_id in (select d.id from deleted_batches d);
  delete from ingest.staged_chunks c where c.batch_id in (select d.id from deleted_batches d);
  delete from ingest.pending_errors e where e.batch_id in (select d.id from deleted_batches d);
  return null;
end;
$$;
create trigger import_batches_drop_staging
  after delete on public.import_batches
  referencing old table as deleted_batches
  for each statement execute function app.import_batches_drop_staging();

create or replace function app.import_file_state(p_batch_id uuid, p_file_no smallint)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'file_no', f.file_no, 'entity', f.entity, 'status', f.status, 'source_stored', f.source_stored,
    'rows_total', f.rows_total, 'rows_staged', f.rows_staged, 'rows_new', f.rows_new, 'rows_existing', f.rows_existing,
    'error_count', f.error_count, 'warning_count', f.warning_count, 'errors_stored', f.errors_stored,
    'error_counts', f.error_counts, 'merged_through_row', f.merged_through_row, 'counts', f.counts)
  from public.import_files f
  where f.batch_id = p_batch_id and f.file_no = p_file_no;
$$;

create or replace function app.import_batch_state(p_batch_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'batch_id', b.id, 'status', b.status, 'commit_mode', b.commit_mode,
    'rows_total', b.rows_total, 'rows_staged', b.rows_staged,
    'error_count', b.error_count, 'warning_count', b.warning_count,
    'counts', b.counts, 'progress', b.progress - 'timings',
    'failure_code', b.failure_code, 'failure_detail', b.failure_detail,
    'validated_at', b.validated_at, 'commit_started_at', b.commit_started_at, 'last_step_at', b.last_step_at,
    'finished_at', b.finished_at, 'expires_at', b.expires_at)
  from public.import_batches b
  where b.id = p_batch_id;
$$;

-- Whether the UNLOGGED staging of a batch still holds what its logged counters say: per file, the
-- chunk bookkeeping must account for rows_total rows sent and rows_staged rows staged, and with
-- p_exact the staged rows themselves are counted (cheap up to the 5,000 rows of an atomic commit).
-- Crash recovery, a failover or a restore empties both staging tables; in a validated batch every
-- row 1..rows_total of every file is staged (a duplicate key is an error), so any loss shows here.
create or replace function app.import_staging_intact(p_batch_id uuid, p_exact boolean)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select not exists (
    select 1
    from public.import_files f
    cross join lateral (
      select coalesce(sum(c.row_count), 0) as sent, coalesce(sum((c.result ->> 'staged')::integer), 0) as staged
      from ingest.staged_chunks c
      where c.batch_id = f.batch_id and c.file_no = f.file_no
    ) as k
    where f.batch_id = p_batch_id
      and (k.sent <> f.rows_total
        or k.staged <> f.rows_staged
        or (p_exact and f.rows_staged <> (select count(*) from ingest.staged_rows s
                                          where s.batch_id = f.batch_id and s.file_no = f.file_no))));
$$;

-- All or nothing (at most 5,000 staged rows), under the import lock: statistics, re-validation of
-- references and required-for-new columns, then every merge in load order inside one
-- subtransaction. Any failure leaves the targets unchanged and the batch invalid with its errors.
create or replace function app.import_commit_atomic(p_batch_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org uuid;
  v_file record;
  v_t0 timestamptz := clock_timestamp();
  v_counts jsonb;
  v_current smallint;
  v_state text;
  v_message text;
  v_hint text;
  v_constraint text;
  v_failure text;
  v_errors integer;
  v_ms integer;
begin
  select b.organization_id into v_org from public.import_batches b where b.id = p_batch_id;
  perform app.import_prepare_stats(p_batch_id, app.import_batch_tables(p_batch_id));

  for v_file in
    select f.file_no, f.rows_total
    from public.import_files f
    join ingest.contract_entities e on e.entity = f.entity
    where f.organization_id = v_org and f.batch_id = p_batch_id
    order by e.load_order, f.file_no
  loop
    v_current := coalesce(v_current, v_file.file_no);
    if v_file.rows_total > 0 then
      perform app.import_check_refs(p_batch_id, v_file.file_no, 1, v_file.rows_total, 'commit');
      perform app.import_flush_errors(p_batch_id, v_file.file_no);
    end if;
  end loop;
  select b.error_count into v_errors from public.import_batches b where b.id = p_batch_id;

  if v_errors > 0 then
    v_failure := 'changed_during_commit';
    v_message := 'references, required columns or stored values changed after validation';
  else
    begin
      for v_file in
        select f.id, f.file_no, f.entity, f.rows_total, f.columns
        from public.import_files f
        join ingest.contract_entities e on e.entity = f.entity
        where f.organization_id = v_org and f.batch_id = p_batch_id
        order by e.load_order, f.file_no
      loop
        v_current := v_file.file_no;
        v_counts := '{}'::jsonb;
        if v_file.rows_total > 0 then
          v_counts := app.import_merge_unit(p_batch_id, v_file.file_no, v_file.entity, 1, v_file.rows_total, 1);
          if v_file.entity = 'locations' and 'parent_location_code' = any (v_file.columns) then
            v_counts := app.import_add_counts(v_counts,
              app.import_merge_unit(p_batch_id, v_file.file_no, 'locations', 1, v_file.rows_total, 2));
          end if;
        end if;
        update public.import_files f
        set counts = app.import_add_counts(f.counts, v_counts), status = 'merged', merged_through_row = f.rows_total
        where f.id = v_file.id;
        update public.import_batches b
        set counts = jsonb_set(b.counts, array[v_file.entity], app.import_add_counts(b.counts -> v_file.entity, v_counts))
        where b.id = p_batch_id;
        -- The batch may have inserted a large share of a parent that later files look codes up in.
        if exists (select 1
                   from public.import_files f2
                   join ingest.contract_columns c on c.entity = f2.entity and c.lookup_entity = v_file.entity
                   where f2.batch_id = p_batch_id and f2.status = 'sealed' and f2.entity <> v_file.entity) then
          perform app.import_prepare_stats(p_batch_id, array[v_file.entity]);
        end if;
      end loop;
    exception when others then
      get stacked diagnostics v_state = returned_sqlstate, v_message = message_text, v_hint = pg_exception_hint,
                              v_constraint = constraint_name;
      if v_state in ('40P01', '40001', '55P03') then
        raise;
      end if;
      v_failure := app.import_failure_code(v_state, v_hint, v_constraint);
      perform app.import_add_error(p_batch_id, v_current, v_failure,
        jsonb_build_object('phase', 'commit', 'sqlstate', v_state, 'message', left(v_message, 300)));
    end;
  end if;

  v_ms := round(extract(epoch from clock_timestamp() - v_t0) * 1000)::integer;
  if v_failure is not null then
    update public.import_batches b
    set status = 'invalid', failure_code = v_failure,
        failure_detail = left(v_failure || ': ' || coalesce(v_message, ''), 500),
        last_step_at = clock_timestamp(), expires_at = now() + interval '24 hours',
        progress = jsonb_build_object('phase', 'failed', 'steps', 1,
                                      'timings', app.import_append_timing(null, 'atomic', v_ms))
    where b.id = p_batch_id;
  else
    perform app.import_drop_staging(p_batch_id, 20000);
    update public.import_batches b
    set status = 'succeeded', finished_at = now(), last_step_at = clock_timestamp(),
        progress = jsonb_build_object('phase', 'done', 'steps', 1,
                                      'timings', app.import_append_timing(null, 'atomic', v_ms))
    where b.id = p_batch_id;
  end if;
  return jsonb_build_object('unit', 'atomic', 'ms', v_ms, 'failure_code', v_failure);
end;
$$;

-- One unit of a stepped commit (the caller holds the import lock and the batch row):
-- prepare (statistics) / merge of the next row range of the next file in load order (locations
-- in two passes: columns, then parents) / stats (after a parent entity) / cleanup (staging rows in
-- slices, then succeeded). A merge range first re-checks references, required-for-new columns and
-- the effective-value row rules (recorded as commit-phase errors); a failure inside the merge's
-- subtransaction marks the batch
-- failed with the cursor kept, so import_resume retries the same unit.
create or replace function app.import_commit_unit(p_batch_id uuid, p_max_rows integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_batch public.import_batches;
  v_file public.import_files;
  v_progress jsonb;
  v_phase text;
  v_unit text;
  v_t0 timestamptz := clock_timestamp();
  v_pass integer;
  v_through integer;
  v_size integer;
  v_from integer;
  v_to integer;
  v_counts jsonb;
  v_flush jsonb;
  v_state text;
  v_hint text;
  v_message text;
  v_constraint text;
  v_failure text;
  v_status text := 'committing';
  v_ms integer;
begin
  select * into v_batch from public.import_batches b where b.id = p_batch_id;
  v_progress := v_batch.progress;
  v_phase := coalesce(v_progress ->> 'phase', 'prepare');

  if v_phase = 'prepare' then
    perform app.import_prepare_stats(p_batch_id, app.import_batch_tables(p_batch_id));
    v_unit := 'prepare';
    v_progress := v_progress || jsonb_build_object('phase', 'merge');
  elsif v_phase = 'stats' then
    v_unit := 'stats:' || coalesce(v_progress ->> 'stats_for', '');
    perform app.import_prepare_stats(p_batch_id, array[v_progress ->> 'stats_for']);
    v_progress := (v_progress - 'stats_for') || jsonb_build_object('phase', 'merge');
  elsif v_phase = 'merge' then
    select f.* into v_file
    from public.import_files f
    join ingest.contract_entities e on e.entity = f.entity
    where f.organization_id = v_batch.organization_id and f.batch_id = p_batch_id and f.status = 'sealed'
    order by e.load_order, f.file_no
    limit 1;
    if v_file.id is null then
      v_phase := 'cleanup';
      v_progress := v_progress || jsonb_build_object('phase', 'cleanup');
    else
      if (v_progress ->> 'file_no')::integer is not distinct from v_file.file_no::integer then
        v_pass := coalesce((v_progress ->> 'pass')::integer, 1);
        v_through := coalesce((v_progress ->> 'through_row')::integer, 0);
      else
        v_pass := 1;
        v_through := 0;
      end if;
      -- The supersession and location-parent cycle guards run after each statement, and the
      -- holiday exclusion constraint per row: a file split over units could pass through a state
      -- in between (a reversed edge inserted before the edge it replaces is updated) that the final
      -- graph, checked at seal, never has. Such files (location parents: the second pass) merge in
      -- one unit, whatever the client asks for, up to 10,000 rows (measured: 20,000 supersessions
      -- take 5.3 s, foreign keys and guards included, too close to the 8 s statement timeout);
      -- larger files fall back to ranges.
      select case
               when (v_file.entity in ('item_supersessions', 'holiday_overrides') or v_pass = 2)
                    and v_file.rows_total <= 10000
                 then greatest(v_file.rows_total, 1)
               else least(coalesce(p_max_rows, e.merge_rows), e.merge_rows)
             end
        into v_size
      from ingest.contract_entities e where e.entity = v_file.entity;
      v_from := v_through + 1;
      v_to := least(v_through + v_size, v_file.rows_total);
      v_unit := format('merge:%s:%s:%s-%s', v_file.entity, v_file.file_no, v_from, v_to)
                || case when v_pass = 2 then ':parents' else '' end;

      -- Every row of the range must still be staged (UNLOGGED staging is emptied by crash
      -- recovery, a failover or a restore); merging what is left would end as succeeded with
      -- rows missing.
      if v_to >= v_from
         and (select count(*) from ingest.staged_rows s
              where s.batch_id = p_batch_id and s.file_no = v_file.file_no
                and s.row_no between v_from and v_to) <> v_to - v_from + 1 then
        v_failure := 'staging_lost';
        v_message := format('rows %s to %s of file %s are no longer staged on the server', v_from, v_to, v_file.file_no);
      end if;

      if v_to >= v_from and v_failure is null then
        -- The merges pin nested loops, so the target's statistics must not be far behind: the
        -- units before this one may have grown it from nothing, and statistics claiming (almost)
        -- no rows put the target on the outer side, rescanning the staged rows once per target
        -- row. Analyze when they claim none, under half of its pages, or fewer rows than this batch
        -- has already inserted (new rows can fill dead space, so the pages alone may not grow;
        -- demand is partitioned: its merge analyzes the month partitions itself).
        if exists (select 1
                   from pg_catalog.pg_class c
                   where c.oid = pg_catalog.to_regclass('public.' || v_file.entity) and c.relkind = 'r'
                     and pg_catalog.pg_relation_size(c.oid) > 0
                     and (c.reltuples <= 0
                          or pg_catalog.pg_relation_size(c.oid) / current_setting('block_size')::integer > c.relpages * 2 + 8
                          or coalesce((v_batch.counts -> v_file.entity ->> 'inserted')::bigint, 0) > c.reltuples)) then
          perform app.import_prepare_stats(p_batch_id, array[v_file.entity]);
        end if;
        if v_pass = 1 then
          perform app.import_check_refs(p_batch_id, v_file.file_no, v_from, v_to, 'commit');
          v_flush := app.import_flush_errors(p_batch_id, v_file.file_no);
          if (v_flush ->> 'errors')::integer > 0 then
            v_failure := 'changed_during_commit';
            v_message := 'references, required columns or stored values changed after validation';
          end if;
        end if;
        if v_failure is null then
          begin
            v_counts := app.import_merge_unit(p_batch_id, v_file.file_no, v_file.entity, v_from, v_to, v_pass);
          exception when others then
            get stacked diagnostics v_state = returned_sqlstate, v_message = message_text, v_hint = pg_exception_hint,
                                    v_constraint = constraint_name;
            if v_state in ('40P01', '40001', '55P03') then
              raise;
            end if;
            v_failure := app.import_failure_code(v_state, v_hint, v_constraint);
            perform app.import_add_error(p_batch_id, v_file.file_no, v_failure,
              jsonb_build_object('phase', 'commit', 'unit', v_unit, 'sqlstate', v_state, 'message', left(v_message, 300)));
          end;
        end if;
      end if;

      if v_failure is null then
        if v_counts is not null then
          update public.import_files f set counts = app.import_add_counts(f.counts, v_counts) where f.id = v_file.id;
          update public.import_batches b
          set counts = jsonb_set(b.counts, array[v_file.entity], app.import_add_counts(b.counts -> v_file.entity, v_counts))
          where b.id = p_batch_id;
        end if;
        if v_pass = 1 and v_to >= v_from then
          update public.import_files f set merged_through_row = v_to where f.id = v_file.id;
        end if;
        if v_to < v_file.rows_total then
          v_progress := v_progress || jsonb_build_object('file_no', v_file.file_no, 'pass', v_pass, 'through_row', v_to);
        elsif v_file.entity = 'locations' and v_pass = 1 and v_file.rows_total > 0
              and 'parent_location_code' = any (v_file.columns) then
          v_progress := v_progress || jsonb_build_object('file_no', v_file.file_no, 'pass', 2, 'through_row', 0);
        else
          update public.import_files f set status = 'merged', merged_through_row = f.rows_total where f.id = v_file.id;
          v_progress := v_progress - 'file_no' - 'pass' - 'through_row';
          if exists (select 1
                     from public.import_files f2
                     join ingest.contract_columns c on c.entity = f2.entity and c.lookup_entity = v_file.entity
                     where f2.batch_id = p_batch_id and f2.status = 'sealed' and f2.entity <> v_file.entity) then
            v_progress := v_progress || jsonb_build_object('phase', 'stats', 'stats_for', v_file.entity);
          end if;
        end if;
      elsif v_failure = 'staging_lost' then
        -- Nothing left to resume from: the import ends; the rows earlier units applied stay.
        v_status := 'expired';
      else
        v_status := 'failed';
      end if;
    end if;
  end if;

  if v_phase = 'cleanup' then
    v_unit := 'cleanup';
    if app.import_drop_staging(p_batch_id, 50000) < 50000 then
      v_status := 'succeeded';
      v_progress := v_progress || jsonb_build_object('phase', 'done');
    end if;
  end if;

  v_ms := round(extract(epoch from clock_timestamp() - v_t0) * 1000)::integer;
  v_progress := v_progress
    || jsonb_build_object('steps', coalesce((v_progress ->> 'steps')::integer, 0) + 1,
                          'timings', app.import_append_timing(v_progress -> 'timings', v_unit, v_ms));
  update public.import_batches b
  set progress = v_progress,
      status = v_status,
      last_step_at = clock_timestamp(),
      failure_code = v_failure,
      failure_detail = case when v_failure is not null then left(v_failure || ': ' || coalesce(v_message, ''), 500) end,
      finished_at = case when v_status in ('succeeded', 'expired') then now() else b.finished_at end,
      expires_at = case when v_status = 'failed' then now() + interval '24 hours'
                        when v_status = 'expired' then null
                        else b.expires_at end
  where b.id = p_batch_id;

  return jsonb_build_object('unit', v_unit, 'ms', v_ms, 'status', v_status, 'failure_code', v_failure);
end;
$$;

------------------------------------------------------------------------------------------------
-- Cycle guards (Step 4; body-only change, same triggers, same errors): walk the chain with one
-- primary-key probe per step. The recursive CTE they replace was planned from the table's
-- statistics, and while one statement inserted thousands of rows into a table whose statistics
-- still said empty, every row's check scanned the rows inserted so far (measured: 2,000 new
-- supersessions 5 s, 20,000 more than 5 minutes; with the walk 20,000 take about 4 s, triggers
-- and foreign keys included). The graph without the new edge is acyclic (every write passes this
-- guard under the per-organization advisory lock), so the walk ends at a root; the step bound is a
-- safety net only.
------------------------------------------------------------------------------------------------

create or replace function app.guard_supersession_cycle()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_item uuid := new.successor_item_id;
  v_steps integer := 0;
begin
  perform pg_advisory_xact_lock(hashtextextended('maqdar.supersessions:' || new.organization_id::text, 0));
  while v_item is not null loop
    if v_item = new.predecessor_item_id or v_steps >= 1000000 then
      raise exception using errcode = 'MQ422', message = 'this supersession would create a cycle',
        hint = 'successor_item_code';
    end if;
    select s.successor_item_id into v_item
    from public.item_supersessions s
    where s.organization_id = new.organization_id and s.predecessor_item_id = v_item;
    v_steps := v_steps + 1;
  end loop;
  return null;
end;
$$;

create or replace function app.guard_location_parent_cycle()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_location uuid := new.parent_location_id;
  v_steps integer := 0;
begin
  if new.parent_location_id is null then
    return null;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('maqdar.locations:' || new.organization_id::text, 0));
  while v_location is not null loop
    if v_location = new.id or v_steps >= 1000000 then
      raise exception using errcode = 'MQ422', message = 'this parent would create a cycle',
        hint = 'parent_location_id';
    end if;
    select l.parent_location_id into v_location
    from public.locations l
    where l.organization_id = new.organization_id and l.id = v_location;
    v_steps := v_steps + 1;
  end loop;
  return null;
end;
$$;

------------------------------------------------------------------------------------------------
-- The delete guard waits for a running import step (body-only change; the policy and the
-- statement-level trigger stay as they are)
------------------------------------------------------------------------------------------------

create or replace function app.refuse_delete_with_demand()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_org uuid;
begin
  if coalesce(current_setting('maqdar.demand_guard', true), '') = 'off' then
    return null;
  end if;
  -- Import steps hold maqdar.import:<org> exclusively while they write demand; wait for the
  -- running step (at most a few seconds) so the probe below sees the demand it commits.
  for v_org in select distinct o.organization_id from deleted_rows o order by 1 loop
    perform pg_advisory_xact_lock_shared(hashtextextended('maqdar.import:' || v_org::text, 0));
  end loop;
  if not exists (
    select 1 from public.demand_history d
    where d.organization_id in (select distinct o.organization_id from deleted_rows o)
  ) then
    return null;
  end if;
  if tg_table_name = 'items' then
    perform 1 from deleted_rows o
      join public.demand_history d on d.organization_id = o.organization_id and d.item_id = o.id
      limit 1;
  else
    perform 1 from deleted_rows o
      join public.demand_history d on d.organization_id = o.organization_id and d.location_id = o.id
      limit 1;
  end if;
  if found then
    raise exception using errcode = 'MQ409',
      message = format('%s with demand history cannot be deleted; mark it inactive instead', tg_table_name);
  end if;
  return null;
end;
$$;

------------------------------------------------------------------------------------------------
-- Public RPCs (authenticated only)
------------------------------------------------------------------------------------------------

-- Creates a batch and its files. Idempotent on p_batch_id when the organization, the caller and
-- the manifest hash match; MQ409 otherwise. Caps: 3 open batches (MQ409), 50 created per 24 hours
-- (MQ429, counted in the ledger ingest.import_creations, so deleted imports still count), 60 files,
-- 1,000,000 rows, 50,000,000 bytes per file (MQ422).
create or replace function public.import_create_batch(p_batch_id uuid, p_organization_id uuid, p_files jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := app.require_user();
  v_hash bytea;
  v_existing public.import_batches;
  v_f jsonb;
  v_ord bigint;
  v_contract ingest.contract_entities;
  v_file_no smallint;
  v_file_nos smallint[] := '{}';
  v_entities text[] := '{}';
  v_entity text;
  v_text text;
  v_extension text;
  v_size bigint;
  v_rows integer;
  v_rows_sum integer := 0;
  v_cols text[];
  v_unknown text;
  v_header text[];
  v_mapping jsonb;
  v_parse jsonb;
  v_group jsonb;
begin
  perform app.require_import_editor(p_organization_id);
  if p_batch_id is null then
    raise exception using errcode = 'MQ422', message = 'an import id is required', hint = 'batch_id';
  end if;
  if p_files is null or jsonb_typeof(p_files) <> 'array' or jsonb_array_length(p_files) not between 1 and 60
     or octet_length(p_files::text) > 262144 then
    raise exception using errcode = 'MQ422', message = 'an import has 1 to 60 files', hint = 'files';
  end if;
  v_hash := sha256(convert_to(p_files::text, 'UTF8'));

  perform pg_advisory_xact_lock(hashtextextended('maqdar.imports:' || p_organization_id::text, 0));

  -- Ids are global (client-generated v4 UUIDs), so an id already used by another organization is
  -- refused like any other unusable id (MQ409 batch_id). That confirms only that the id exists,
  -- never its organization or content, and only to someone who already knows the unguessable id:
  -- accepted, unlike the RPCs on an existing import, which answer MQ404 batch_id to non-members.
  select * into v_existing from public.import_batches b where b.id = p_batch_id;
  if v_existing.id is not null then
    if v_existing.organization_id = p_organization_id and v_existing.created_by = v_user
       and v_existing.files_sha256 = v_hash then
      return app.import_batch_state(v_existing.id) || jsonb_build_object('files', (
        select coalesce(jsonb_agg(jsonb_build_object('file_no', f.file_no, 'entity', f.entity, 'storage_path', f.storage_path)
                                  order by f.file_no), '[]'::jsonb)
        from public.import_files f
        where f.organization_id = v_existing.organization_id and f.batch_id = v_existing.id));
    end if;
    raise exception using errcode = 'MQ409', message = 'this import id is already in use', hint = 'batch_id';
  end if;

  if (select count(*) from public.import_batches b
      where b.organization_id = p_organization_id
        and b.status in ('staging', 'validated', 'invalid', 'committing', 'failed')) >= 3 then
    raise exception using errcode = 'MQ409', message = 'finish, cancel or delete an open import first (at most 3 open imports)',
      hint = 'open_batches';
  end if;
  -- The ledger, not import_batches: deleting imports must not reset the cap.
  delete from ingest.import_creations c
  where c.organization_id = p_organization_id and c.created_at <= now() - interval '24 hours';
  if (select count(*) from ingest.import_creations c
      where c.organization_id = p_organization_id and c.created_at > now() - interval '24 hours') >= 50 then
    raise exception using errcode = 'MQ429', message = 'too many imports in the last 24 hours (at most 50)', hint = 'batches_per_day';
  end if;

  insert into public.import_batches (id, organization_id, source, status, created_by, files_sha256, file_count, expires_at)
  values (p_batch_id, p_organization_id, 'wizard', 'staging', v_user, v_hash, jsonb_array_length(p_files),
          now() + interval '24 hours');
  insert into ingest.import_creations (organization_id, batch_id) values (p_organization_id, p_batch_id);

  for v_f, v_ord in select e.value, e.ordinality from jsonb_array_elements(p_files) with ordinality as e loop
    if jsonb_typeof(v_f) <> 'object' then
      raise exception using errcode = 'MQ422', message = format('file %s is not an object', v_ord), hint = 'files';
    end if;

    v_text := v_f ->> 'file_no';
    if coalesce(jsonb_typeof(v_f -> 'file_no'), '') <> 'number' or v_text !~ '^[0-9]{1,2}$'
       or v_text::integer not between 1 and 60 then
      raise exception using errcode = 'MQ422', message = format('file %s: file_no is 1 to 60', v_ord), hint = 'file_no';
    end if;
    v_file_no := v_text::smallint;
    if v_file_no = any (v_file_nos) then
      raise exception using errcode = 'MQ422', message = format('file number %s appears twice', v_file_no), hint = 'file_no';
    end if;
    v_file_nos := v_file_nos || v_file_no;

    v_entity := v_f ->> 'entity';
    select * into v_contract from ingest.contract_entities e where e.entity = v_entity;
    if v_contract.entity is null then
      raise exception using errcode = 'MQ422', message = format('file %s: unknown entity', v_file_no), hint = 'mapping';
    end if;
    if not v_contract.monthly_parts and v_entity = any (v_entities) then
      raise exception using errcode = 'MQ422', message = format('%s appears in more than one file', v_entity), hint = 'files';
    end if;
    v_entities := v_entities || v_entity;

    if coalesce(jsonb_typeof(v_f -> 'original_name'), '') <> 'string'
       or char_length(v_f ->> 'original_name') not between 1 and 255 then
      raise exception using errcode = 'MQ422', message = format('file %s: original_name has 1 to 255 characters', v_file_no),
        hint = 'original_name';
    end if;
    v_extension := v_f ->> 'extension';
    if v_extension is null or v_extension not in ('csv', 'tsv', 'txt', 'xlsx') then
      raise exception using errcode = 'MQ422', message = format('file %s: extension is csv, tsv, txt or xlsx', v_file_no),
        hint = 'extension';
    end if;
    if coalesce(jsonb_typeof(v_f -> 'content_type'), 'null') not in ('null', 'string')
       or char_length(coalesce(v_f ->> 'content_type', '')) > 255 then
      raise exception using errcode = 'MQ422', message = format('file %s: content_type is invalid', v_file_no),
        hint = 'content_type';
    end if;
    v_text := v_f ->> 'size_bytes';
    if coalesce(jsonb_typeof(v_f -> 'size_bytes'), '') <> 'number' or v_text !~ '^[0-9]{1,8}$'
       or v_text::bigint > 50000000 then
      raise exception using errcode = 'MQ422', message = format('file %s: at most 50,000,000 bytes per file', v_file_no),
        hint = 'size_bytes';
    end if;
    v_size := v_text::bigint;
    if coalesce(v_f ->> 'sha256', '') !~ '^[0-9a-f]{64}$' then
      raise exception using errcode = 'MQ422', message = format('file %s: sha256 is 64 lower-case hex digits', v_file_no),
        hint = 'sha256';
    end if;
    v_text := v_f ->> 'rows_total';
    if coalesce(jsonb_typeof(v_f -> 'rows_total'), '') <> 'number' or v_text !~ '^[0-9]{1,7}$'
       or v_text::integer > 1000000 then
      raise exception using errcode = 'MQ422', message = format('file %s: rows_total is 0 to 1,000,000', v_file_no),
        hint = 'rows_total';
    end if;
    v_rows := v_text::integer;
    v_rows_sum := v_rows_sum + v_rows;
    if v_rows_sum > 1000000 then
      raise exception using errcode = 'MQ422', message = 'an import has at most 1,000,000 rows', hint = 'rows_total';
    end if;

    if coalesce(jsonb_typeof(v_f -> 'columns'), '') <> 'array' or jsonb_array_length(v_f -> 'columns') not between 1 and 64
       or exists (select 1 from jsonb_array_elements(v_f -> 'columns') as x where jsonb_typeof(x) <> 'string') then
      raise exception using errcode = 'MQ422', message = format('file %s: columns is a list of contract column names', v_file_no),
        hint = 'mapping';
    end if;
    v_cols := array(select x from jsonb_array_elements_text(v_f -> 'columns') as x);
    if cardinality(v_cols) <> (select count(distinct x) from unnest(v_cols) as x) then
      raise exception using errcode = 'MQ422', message = format('file %s: a column is mapped twice', v_file_no), hint = 'mapping';
    end if;
    select string_agg(x, ', ') into v_unknown
    from unnest(v_cols) as x
    where not exists (select 1 from ingest.contract_columns c where c.entity = v_entity and c.name = x);
    if v_unknown is not null then
      raise exception using errcode = 'MQ422', message = format('file %s: %s is not a column of %s', v_file_no, left(v_unknown, 200), v_entity),
        hint = 'mapping';
    end if;
    if not (v_contract.natural_key <@ v_cols) then
      raise exception using errcode = 'MQ422',
        message = format('file %s: map every key column (%s)', v_file_no, array_to_string(v_contract.natural_key, ', ')),
        hint = 'mapping';
    end if;
    select g into v_group
    from jsonb_array_elements(v_contract.column_groups) as g
    where (select count(*) from jsonb_array_elements_text(g) as x where x = any (v_cols)) not in (0, jsonb_array_length(g))
    limit 1;
    if v_group is not null then
      raise exception using errcode = 'MQ422',
        message = format('file %s: the columns %s are mapped together or not at all', v_file_no,
                         (select string_agg(x, ', ') from jsonb_array_elements_text(v_group) as x)),
        hint = 'mapping';
    end if;
    if v_entity = 'demand_history' and not (v_cols && array['quantity', 'lost_sales_quantity']) then
      raise exception using errcode = 'MQ422', message = format('file %s: map quantity, lost_sales_quantity or both', v_file_no),
        hint = 'mapping';
    end if;
    v_cols := array(select c.name from ingest.contract_columns c where c.entity = v_entity and c.name = any (v_cols) order by c.position);

    if coalesce(jsonb_typeof(v_f -> 'header'), 'null') = 'null' then
      v_header := '{}';
    elsif jsonb_typeof(v_f -> 'header') <> 'array' or jsonb_array_length(v_f -> 'header') > 64
          or exists (select 1 from jsonb_array_elements(v_f -> 'header') as x
                     where jsonb_typeof(x) <> 'string' or char_length(x #>> '{}') > 500) then
      raise exception using errcode = 'MQ422', message = format('file %s: header is at most 64 texts of 500 characters', v_file_no),
        hint = 'header';
    else
      v_header := array(select x from jsonb_array_elements_text(v_f -> 'header') as x);
    end if;
    v_mapping := coalesce(nullif(v_f -> 'mapping', 'null'::jsonb), '{}'::jsonb);
    if jsonb_typeof(v_mapping) <> 'object' or octet_length(v_mapping::text) > 32768
       or (select count(*) from jsonb_object_keys(v_mapping)) > 64 then
      raise exception using errcode = 'MQ422', message = format('file %s: mapping is an object of at most 64 columns', v_file_no),
        hint = 'mapping';
    end if;
    v_parse := coalesce(nullif(v_f -> 'parse', 'null'::jsonb), '{}'::jsonb);
    if jsonb_typeof(v_parse) <> 'object' or octet_length(v_parse::text) > 4096 then
      raise exception using errcode = 'MQ422', message = format('file %s: parse is an object of at most 4 KB', v_file_no),
        hint = 'parse';
    end if;

    insert into public.import_files (organization_id, batch_id, file_no, entity, original_name, content_type, extension,
                                     size_bytes, sha256, storage_path, header, columns, mapping, parse, rows_total)
    values (p_organization_id, p_batch_id, v_file_no, v_entity, v_f ->> 'original_name', v_f ->> 'content_type', v_extension,
            v_size, decode(v_f ->> 'sha256', 'hex'),
            p_organization_id::text || '/' || p_batch_id::text || '/' || v_file_no::text || '.' || v_extension,
            v_header, v_cols, v_mapping, v_parse, v_rows);
  end loop;

  update public.import_batches b set rows_total = v_rows_sum where b.id = p_batch_id;
  perform app.import_sweep(20000);

  return app.import_batch_state(p_batch_id) || jsonb_build_object('files', (
    select coalesce(jsonb_agg(jsonb_build_object('file_no', f.file_no, 'entity', f.entity, 'storage_path', f.storage_path)
                              order by f.file_no), '[]'::jsonb)
    from public.import_files f
    where f.organization_id = p_organization_id and f.batch_id = p_batch_id));
end;
$$;
comment on function public.import_create_batch(uuid, uuid, jsonb) is 'Creates an import with its files (editors; MQ403/MQ404 otherwise). Idempotent on p_batch_id with the same caller, organization and files. MQ409 open_batches (3), MQ429 batches_per_day (50), MQ422 with the offending field as hint. Returns the batch state and files[{file_no, entity, storage_path}].';

-- Stages one chunk: a JSON array of [row_no, cell_1 .. cell_n] (n = contract columns of the
-- entity; null exactly for the columns the file does not provide, a string otherwise, at most
-- 4,000 characters), row_no running from p_first_row. An exact replay returns the stored result;
-- an overlap is MQ409. Duplicate keys become duplicate_key errors, then cells, references and row
-- rules of the range are checked.
create or replace function public.import_stage_chunk(p_batch_id uuid, p_file_no smallint, p_first_row integer, p_rows text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_batch public.import_batches;
  v_file public.import_files;
  v_hash bytea;
  v_chunk ingest.staged_chunks;
  v_rows jsonb;
  v_count integer;
  v_last integer;
  v_limit integer;
  v_provided boolean[];
  v_ncols integer;
  v_types jsonb;
  v_bad integer;
  v_first_bad integer;
  v_staged integer;
  v_flush jsonb;
  v_result jsonb;
begin
  v_batch := app.import_batch_for_editor(p_batch_id, true);
  select * into v_file from public.import_files f
  where f.organization_id = v_batch.organization_id and f.batch_id = v_batch.id and f.file_no = p_file_no
  for update;
  if v_file.id is null then
    raise exception using errcode = 'MQ404', message = 'no such file in this import', hint = 'file_no';
  end if;

  v_hash := sha256(convert_to(coalesce(p_rows, ''), 'UTF8'));
  select * into v_chunk from ingest.staged_chunks c
  where c.batch_id = v_batch.id and c.file_no = p_file_no and c.first_row_no = p_first_row;
  if v_chunk.batch_id is not null then
    if v_chunk.rows_sha256 = v_hash then
      return v_chunk.result || jsonb_build_object('replayed', true);
    end if;
    raise exception using errcode = 'MQ409', message = 'a different chunk was already staged at this row', hint = 'first_row';
  end if;

  if v_batch.status <> 'staging' then
    raise exception using errcode = 'MQ409', message = format('the import is %s, not staging', v_batch.status), hint = 'status';
  end if;
  if v_file.status <> 'staging' then
    raise exception using errcode = 'MQ409', message = 'this file is already sealed', hint = 'status';
  end if;
  if exists (
    select 1 from public.import_files f
    where f.organization_id = v_batch.organization_id and f.batch_id = v_batch.id and f.status = 'staging'
      and f.entity in (select c.lookup_entity from ingest.contract_columns c
                       where c.entity = v_file.entity and c.lookup_entity is not null and c.lookup_entity <> v_file.entity)
  ) then
    raise exception using errcode = 'MQ409', message = 'seal the files this file refers to first', hint = 'parent';
  end if;

  if p_first_row is null or p_first_row < 1 then
    raise exception using errcode = 'MQ422', message = 'first_row starts at 1', hint = 'first_row';
  end if;
  if p_rows is null or octet_length(p_rows) > 1048576 or not pg_catalog.pg_input_is_valid(p_rows, 'jsonb') then
    raise exception using errcode = 'MQ422', message = 'rows is a JSON array of at most 1 MB', hint = 'rows';
  end if;
  v_rows := p_rows::jsonb;
  select e.stage_rows into v_limit from ingest.contract_entities e where e.entity = v_file.entity;
  if jsonb_typeof(v_rows) <> 'array' or jsonb_array_length(v_rows) not between 1 and v_limit then
    raise exception using errcode = 'MQ422', message = format('a chunk has 1 to %s rows', v_limit), hint = 'rows';
  end if;
  v_count := jsonb_array_length(v_rows);
  v_last := p_first_row + v_count - 1;
  if v_last > v_file.rows_total then
    raise exception using errcode = 'MQ422', message = format('the file declares %s rows', v_file.rows_total), hint = 'rows';
  end if;
  if exists (select 1 from ingest.staged_chunks c
             where c.batch_id = v_batch.id and c.file_no = p_file_no
               and c.first_row_no <= v_last and c.last_row_no >= p_first_row) then
    raise exception using errcode = 'MQ409', message = 'these rows overlap a staged chunk', hint = 'first_row';
  end if;

  -- One pass: each row must be [row_no, cells...] with the expected JSON type per position
  -- (a string for provided columns, null otherwise) and cells of at most 4,000 characters (above
-- every max_length, so too_long is reported per cell instead of the client cutting values). Nothing
  -- is inserted unless every row passes.
  v_provided := app.import_provided(v_file.entity, v_file.columns);
  v_ncols := cardinality(v_provided);
  v_types := jsonb_build_array('number') || coalesce(
    (select jsonb_agg(case when u.provided then 'string' else 'null' end order by u.i)
     from unnest(v_provided) with ordinality as u(provided, i)), '[]'::jsonb);
  with parsed as materialized (
    select (p_first_row + e.ord - 1)::integer as row_no, x.cells,
           coalesce(jsonb_path_query_array(e.r, '$[*].type()') = v_types
                    and (e.r -> 0) = to_jsonb(p_first_row + e.ord - 1), false)
           and coalesce((select max(char_length(c)) from unnest(x.cells) as c), 0) <= 4000 as ok
    from jsonb_array_elements(v_rows) with ordinality as e(r, ord)
    cross join lateral (
      select array(select e.r ->> i from generate_series(1, v_ncols) as i order by i) as cells
      offset 0
    ) as x
  ), verdict as materialized (
    select count(*) filter (where not p.ok)::integer as bad, min(p.row_no) filter (where not p.ok) as first_bad
    from parsed p
  ), ins as (
    insert into ingest.staged_rows (organization_id, batch_id, file_no, entity, row_no, nk, cells)
    select v_batch.organization_id, v_batch.id, p_file_no, v_file.entity, p.row_no, app.import_nk(v_file.entity, p.cells), p.cells
    from parsed p
    where (select v.bad from verdict v) = 0
    order by p.row_no
    on conflict (batch_id, entity, nk) do nothing
    returning 1
  )
  select v.bad, v.first_bad, (select count(*)::integer from ins) into v_bad, v_first_bad, v_staged
  from verdict v;
  if v_bad > 0 then
    raise exception using errcode = 'MQ422',
      message = format('row %s is not [row_no, %s cells] with null exactly for unmapped columns and at most 4,000 characters per cell',
                       v_first_bad, v_ncols),
      hint = 'rows';
  end if;

  if v_staged < v_count then
    insert into ingest.pending_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value, detail)
    select v_batch.organization_id, v_batch.id, p_file_no, d.row_no, '', 'duplicate_key', 'error',
           left(replace(d.nk, E'\x1f', ' | '), 200), jsonb_build_object('first_row', s.row_no, 'first_file_no', s.file_no)
    from (
      select (p_first_row + e.ord - 1)::integer as row_no,
             app.import_nk(v_file.entity, array(select e.r ->> i from generate_series(1, v_ncols) as i order by i)) as nk
      from jsonb_array_elements(v_rows) with ordinality as e(r, ord)
    ) as d
    join ingest.staged_rows s on s.batch_id = v_batch.id and s.entity = v_file.entity and s.nk = d.nk
    where not (s.file_no = p_file_no and s.row_no = d.row_no);
  end if;

  perform app.import_prepare_stats(v_batch.id, array(
    select v_file.entity
    union
    select c.lookup_entity from ingest.contract_columns c where c.entity = v_file.entity and c.lookup_entity is not null));
  perform app.import_check_cells(v_batch.id, p_file_no, p_first_row, v_last);
  perform app.import_check_refs(v_batch.id, p_file_no, p_first_row, v_last, 'stage');
  v_flush := app.import_flush_errors(v_batch.id, p_file_no);

  update public.import_files f set rows_staged = f.rows_staged + v_staged where f.id = v_file.id;
  update public.import_batches b
  set rows_staged = b.rows_staged + v_staged, expires_at = now() + interval '24 hours'
  where b.id = v_batch.id;

  v_result := jsonb_build_object(
    'file_no', p_file_no, 'first_row', p_first_row, 'last_row', v_last, 'rows', v_count, 'staged', v_staged,
    'duplicates', v_count - v_staged, 'errors_added', (v_flush ->> 'errors')::integer,
    'warnings_added', (v_flush ->> 'warnings')::integer, 'replayed', false,
    'file', app.import_file_state(v_batch.id, p_file_no),
    'batch', app.import_batch_state(v_batch.id) - 'progress' - 'counts');
  insert into ingest.staged_chunks (organization_id, batch_id, file_no, first_row_no, last_row_no, row_count, rows_sha256, result)
  values (v_batch.organization_id, v_batch.id, p_file_no, p_first_row, v_last, v_count, v_hash, v_result);
  return v_result;
end;
$$;
comment on function public.import_stage_chunk(uuid, smallint, integer, text) is 'Stages and checks one chunk of a file (editors). MQ404 file_no, MQ409 status/parent/first_row, MQ422 rows/first_row. Returns {file_no, first_row, last_row, rows, staged, duplicates, errors_added, warnings_added, replayed, file, batch}.';

-- Seals a file once every row is staged: contiguity, the original in Storage (missing: warning
-- source_missing; wrong size: error source_size_mismatch), the set rules. When the last file is
-- sealed the batch becomes validated (no errors) or invalid.
create or replace function public.import_seal_file(p_batch_id uuid, p_file_no smallint, p_rows_total integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_batch public.import_batches;
  v_file public.import_files;
  v_rows bigint;
  v_staged bigint;
  v_first integer;
  v_last integer;
  v_size bigint;
  v_stored boolean := false;
  v_reltuples real;
begin
  v_batch := app.import_batch_for_editor(p_batch_id, true);
  select * into v_file from public.import_files f
  where f.organization_id = v_batch.organization_id and f.batch_id = v_batch.id and f.file_no = p_file_no
  for update;
  if v_file.id is null then
    raise exception using errcode = 'MQ404', message = 'no such file in this import', hint = 'file_no';
  end if;

  if v_file.status = 'staging' then
    if v_batch.status <> 'staging' then
      raise exception using errcode = 'MQ409', message = format('the import is %s, not staging', v_batch.status), hint = 'status';
    end if;
    if p_rows_total is distinct from v_file.rows_total then
      raise exception using errcode = 'MQ422', message = format('the file declares %s rows', v_file.rows_total), hint = 'rows_total';
    end if;
    select coalesce(sum(c.row_count), 0), coalesce(sum((c.result ->> 'staged')::integer), 0), min(c.first_row_no), max(c.last_row_no)
      into v_rows, v_staged, v_first, v_last
    from ingest.staged_chunks c
    where c.batch_id = v_batch.id and c.file_no = p_file_no;
    -- The chunks account for fewer staged rows than the logged counter: the UNLOGGED staging was
    -- emptied (crash recovery, failover, restore) after some chunks were staged.
    if v_staged <> v_file.rows_staged then
      raise exception using errcode = 'MQ409',
        message = 'the staged rows of this file are no longer on the server; cancel and import the files again',
        hint = 'staging_lost';
    end if;
    if v_rows <> v_file.rows_total or (v_file.rows_total > 0 and (v_first <> 1 or v_last <> v_file.rows_total)) then
      raise exception using errcode = 'MQ409', message = format('%s of %s rows are staged', v_rows, v_file.rows_total),
        hint = 'chunks';
    end if;

    select (o.metadata ->> 'size')::bigint, true into v_size, v_stored
    from storage.objects o
    where o.bucket_id = 'imports' and o.name = v_file.storage_path
    limit 1;
    if not coalesce(v_stored, false) then
      insert into ingest.pending_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value, detail)
      values (v_batch.organization_id, v_batch.id, p_file_no, 0, '', 'source_missing', 'warning', null,
              jsonb_build_object('storage_path', v_file.storage_path));
    elsif v_size is distinct from v_file.size_bytes then
      insert into ingest.pending_errors (organization_id, batch_id, file_no, row_no, column_name, code, level, value, detail)
      values (v_batch.organization_id, v_batch.id, p_file_no, 0, '', 'source_size_mismatch', 'error', null,
              jsonb_build_object('expected', v_file.size_bytes, 'actual', v_size));
    else
      update public.import_files f set source_stored = true where f.id = v_file.id;
    end if;

    perform app.import_check_sets(v_batch.id, p_file_no);
    perform app.import_flush_errors(v_batch.id, p_file_no);
    update public.import_files f set status = 'sealed', sealed_at = now() where f.id = v_file.id;

    -- Statistics of the staging table matter for the reference checks and merges of large batches.
    select c.reltuples into v_reltuples from pg_catalog.pg_class c where c.oid = 'ingest.staged_rows'::regclass;
    if v_batch.rows_staged > 0 and v_batch.rows_staged > 0.1 * greatest(v_reltuples, 0) then
      analyze ingest.staged_rows;
    end if;

    if not exists (select 1 from public.import_files f
                   where f.organization_id = v_batch.organization_id and f.batch_id = v_batch.id and f.status = 'staging') then
      update public.import_batches b
      set status = case when b.error_count = 0 then 'validated' else 'invalid' end,
          validated_at = case when b.error_count = 0 then now() end
      where b.id = v_batch.id;
    end if;
    update public.import_batches b set expires_at = now() + interval '24 hours' where b.id = v_batch.id;
  end if;

  return app.import_file_state(v_batch.id, p_file_no)
    || jsonb_build_object('batch', app.import_batch_state(v_batch.id) - 'progress' - 'counts');
end;
$$;
comment on function public.import_seal_file(uuid, smallint, integer) is 'Seals a fully staged file (editors; repeat calls return the state). MQ404 file_no, MQ409 status/chunks/staging_lost, MQ422 rows_total. Returns the file state plus batch.';

-- Commits a validated batch. At most 5,000 staged rows: all or nothing in this call. Larger:
-- each call runs the next unit(s) of a stepped commit (more than one only while the call is under
-- 250 ms) until done. MQ409 import_in_progress (another writer holds the organization's import
-- lock), another_commit (another batch is committing), errors, validation_expired (validated more
-- than 24 hours ago), status. Staging that the server lost (app.import_staging_intact, or a merge
-- range that is no longer fully staged) ends the import as expired with failure_code
-- staging_lost; the call then returns done with that state.
create or replace function public.import_commit_step(p_batch_id uuid, p_max_rows integer default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_batch public.import_batches;
  v_started timestamptz := clock_timestamp();
  v_mode text;
  v_unit jsonb;
  v_units integer := 0;
begin
  v_batch := app.import_batch_for_editor(p_batch_id, false);
  if p_max_rows is not null and p_max_rows < 1 then
    raise exception using errcode = 'MQ422', message = 'max_rows is at least 1', hint = 'max_rows';
  end if;
  if v_batch.status = 'succeeded' then
    return app.import_batch_state(p_batch_id) || jsonb_build_object('done', true, 'units', 0);
  end if;
  if v_batch.status not in ('validated', 'committing') then
    raise exception using errcode = 'MQ409', message = format('the import is %s', v_batch.status), hint = 'status';
  end if;

  -- Not this batch: an idle commit of its own simply continues (the step refreshes last_step_at).
  perform app.import_sweep(0, p_batch_id);
  if not pg_try_advisory_xact_lock(hashtextextended('maqdar.import:' || v_batch.organization_id::text, 0)) then
    raise exception using errcode = 'MQ409', message = 'another import is writing to this organization; try again shortly',
      hint = 'import_in_progress';
  end if;
  select * into v_batch from public.import_batches b where b.id = p_batch_id for update;

  if v_batch.status = 'succeeded' then
    return app.import_batch_state(p_batch_id) || jsonb_build_object('done', true, 'units', 0);
  elsif v_batch.status = 'validated' then
    if v_batch.error_count > 0 then
      raise exception using errcode = 'MQ409', message = 'fix the errors first', hint = 'errors';
    end if;
    if v_batch.validated_at is null or v_batch.validated_at < now() - interval '24 hours' then
      raise exception using errcode = 'MQ409', message = 'the validation is older than 24 hours; import the files again',
        hint = 'validation_expired';
    end if;
    v_mode := case when v_batch.rows_staged <= 5000 then 'atomic' else 'stepped' end;
    -- Staging emptied by crash recovery, a failover or a restore: nothing is written, the import
    -- ends as expired with failure_code staging_lost (returned, not raised, so the state persists).
    if not app.import_staging_intact(p_batch_id, v_mode = 'atomic') then
      update public.import_batches b
      set status = 'expired', failure_code = 'staging_lost',
          failure_detail = 'staging_lost: the checked rows are no longer on the server; import the files again',
          finished_at = now(), expires_at = null
      where b.id = p_batch_id;
      return app.import_batch_state(p_batch_id) || jsonb_build_object('done', true, 'units', 0);
    end if;
    begin
      update public.import_batches b
      set status = 'committing', commit_mode = v_mode, commit_started_at = now(), last_step_at = clock_timestamp(),
          expires_at = null, progress = jsonb_build_object('phase', 'prepare', 'steps', 0)
      where b.id = p_batch_id;
    exception when unique_violation then
      raise exception using errcode = 'MQ409', message = 'another import of this organization is committing',
        hint = 'another_commit';
    end;
    if v_mode = 'atomic' then
      v_unit := app.import_commit_atomic(p_batch_id);
      return app.import_batch_state(p_batch_id)
        || jsonb_build_object('done', true, 'units', 1, 'unit', v_unit ->> 'unit', 'ms', (v_unit ->> 'ms')::integer);
    end if;
  elsif v_batch.status <> 'committing' or v_batch.commit_mode is distinct from 'stepped' then
    raise exception using errcode = 'MQ409', message = format('the import is %s', v_batch.status), hint = 'status';
  end if;

  loop
    v_unit := app.import_commit_unit(p_batch_id, p_max_rows);
    v_units := v_units + 1;
    exit when v_unit ->> 'status' <> 'committing' or clock_timestamp() - v_started > interval '250 milliseconds';
  end loop;
  return app.import_batch_state(p_batch_id)
    || jsonb_build_object('done', v_unit ->> 'status' <> 'committing', 'units', v_units, 'unit', v_unit ->> 'unit',
                          'ms', (v_unit ->> 'ms')::integer);
end;
$$;
comment on function public.import_commit_step(uuid, integer) is 'Commits a validated import: atomically up to 5,000 staged rows, otherwise one short unit per call (editors). Lost staging ends it as expired (failure_code staging_lost). Returns the batch state plus done, units, unit, ms.';

-- Takes a failed stepped commit back to committing; the next step retries the failed unit.
create or replace function public.import_resume(p_batch_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_batch public.import_batches;
begin
  v_batch := app.import_batch_for_editor(p_batch_id, false);
  if v_batch.status <> 'failed' or v_batch.commit_mode is distinct from 'stepped' then
    raise exception using errcode = 'MQ409', message = 'only a failed stepped commit can resume', hint = 'status';
  end if;
  if not pg_try_advisory_xact_lock(hashtextextended('maqdar.import:' || v_batch.organization_id::text, 0)) then
    raise exception using errcode = 'MQ409', message = 'another import is writing to this organization; try again shortly',
      hint = 'import_in_progress';
  end if;
  select * into v_batch from public.import_batches b where b.id = p_batch_id for update;
  if v_batch.status <> 'failed' then
    raise exception using errcode = 'MQ409', message = 'only a failed stepped commit can resume', hint = 'status';
  end if;
  begin
    update public.import_batches b
    set status = 'committing', failure_code = null, failure_detail = null, last_step_at = clock_timestamp(), expires_at = null,
        error_count = 0
    where b.id = p_batch_id;
  exception when unique_violation then
    raise exception using errcode = 'MQ409', message = 'another import of this organization is committing',
      hint = 'another_commit';
  end;
  -- A commit only starts without errors, so every error-level detail and count now comes from
  -- the failed attempt. It no longer holds once the cause is fixed (the next units record it again
  -- if not), and a succeeded import must not show it. Warnings from staging stay.
  delete from public.import_errors e
  where e.organization_id = v_batch.organization_id and e.batch_id = p_batch_id and e.level = 'error';
  update public.import_files f
  set error_count = 0,
      errors_stored = (select count(*)::integer
                       from public.import_errors e
                       where e.organization_id = f.organization_id and e.batch_id = f.batch_id and e.file_no = f.file_no),
      error_counts = (select coalesce(jsonb_object_agg(o.key, o.value), '{}'::jsonb)
                      from jsonb_each(f.error_counts) as o
                      where o.key = any (array['zero_row_new_key', 'source_missing']))
  where f.organization_id = v_batch.organization_id and f.batch_id = p_batch_id and f.error_count > 0;
  return app.import_batch_state(p_batch_id);
end;
$$;
comment on function public.import_resume(uuid) is 'Resumes a failed stepped commit at the unit that failed (editors); the errors of the failed attempt are cleared. MQ409 status/import_in_progress/another_commit.';

-- Cancels an import that is not committing (or whose stepped commit has had no step for 30
-- minutes: it is abandoned, failure_code abandoned): marks it canceled and deletes its staging rows
-- in slices of 20,000; call again until done. Rows a stepped commit applied stay. A running step
-- holds the batch row, so the lock below waits for it and then sees a fresh last_step_at.
create or replace function public.import_cancel_step(p_batch_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_batch public.import_batches;
  v_done boolean;
begin
  v_batch := app.import_batch_for_editor(p_batch_id, true);
  if v_batch.status = 'succeeded'
     or (v_batch.status = 'committing'
         and coalesce(v_batch.last_step_at, v_batch.commit_started_at, '-infinity') >= now() - interval '30 minutes') then
    raise exception using errcode = 'MQ409', message = format('the import is %s', v_batch.status), hint = 'status';
  end if;
  if v_batch.status = 'committing' then
    update public.import_batches b
    set status = 'canceled', failure_code = 'abandoned', failure_detail = 'abandoned: no commit step for 30 minutes',
        finished_at = now(), expires_at = null
    where b.id = p_batch_id;
  elsif v_batch.status in ('staging', 'validated', 'invalid', 'failed') then
    update public.import_batches b
    set status = 'canceled', finished_at = now(), expires_at = null
    where b.id = p_batch_id;
  end if;
  v_done := v_batch.staging_cleared_at is not null or app.import_drop_staging(p_batch_id, 20000) < 20000;
  perform app.import_sweep(0);
  return app.import_batch_state(p_batch_id) || jsonb_build_object('done', v_done);
end;
$$;
comment on function public.import_cancel_step(uuid) is 'Cancels an import that is not committing, or abandons a stepped commit idle for 30 minutes, and clears its staging rows in slices (editors); repeat until done. Applied rows of a stepped commit stay. MQ409 status.';

-- Deletes a finished import with its files and errors. The route removes the originals from
-- Storage first. MQ409 cleanup when more than 50,000 staging rows remain (call import_cancel_step
-- until done first).
create or replace function public.import_delete(p_batch_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_batch public.import_batches;
begin
  v_batch := app.import_batch_for_editor(p_batch_id, true);
  if v_batch.status not in ('succeeded', 'canceled', 'expired') then
    raise exception using errcode = 'MQ409', message = format('the import is %s; cancel it first', v_batch.status), hint = 'status';
  end if;
  -- The delete trigger drops the remaining staging rows; keep that bounded.
  if v_batch.staging_cleared_at is null
     and (select count(*) from (select 1 from ingest.staged_rows s where s.batch_id = p_batch_id limit 50001) as x) > 50000 then
    raise exception using errcode = 'MQ409', message = 'staging rows are still being removed; call import_cancel_step until done',
      hint = 'cleanup';
  end if;
  delete from public.import_batches b where b.id = p_batch_id and b.organization_id = v_batch.organization_id;
end;
$$;
comment on function public.import_delete(uuid) is 'Deletes a succeeded, canceled or expired import with its files and errors (editors). MQ409 status/cleanup.';

------------------------------------------------------------------------------------------------
-- Function privileges: internal helpers for nobody but their owner; RPCs for authenticated only
------------------------------------------------------------------------------------------------

do $$
declare
  f regprocedure;
  v_internal integer := 0;
  v_public integer := 0;
begin
  for f in
    select p.oid::regprocedure
    from pg_catalog.pg_proc p
    join pg_catalog.pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'app'
      and (p.proname like 'import\_%' or p.proname in ('require_import_editor', 'demand_history_window'))
  loop
    execute format('revoke all on function %s from public, anon, authenticated, service_role', f);
    v_internal := v_internal + 1;
  end loop;
  for f in
    select p.oid::regprocedure
    from pg_catalog.pg_proc p
    join pg_catalog.pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in ('import_create_batch', 'import_stage_chunk', 'import_seal_file', 'import_commit_step',
                        'import_resume', 'import_cancel_step', 'import_delete')
  loop
    execute format('revoke all on function %s from public, anon, service_role', f);
    execute format('grant execute on function %s to authenticated', f);
    v_public := v_public + 1;
  end loop;
  if v_public <> 7 or v_internal < 40 then
    raise exception 'unexpected import function count: % public, % internal', v_public, v_internal;
  end if;
end
$$;
